window.GITA=window.GITA||{};GITA.capitulos=GITA.capitulos||{};GITA.capitulos[10]={"numero": 10, "titulo": "El yoga de las manifestaciones divinas", "versos": [{"n": 1, "hablante": "krsna", "sa": ["श्रीभगवानुवाच ।", "भूय एव महाबाहो शृणु मे परमं वचः ।", "यत्तेऽहं प्रीयमाणाय वक्ष्यामि हितकाम्यया ॥१॥"], "iast": ["śrī-bhagavān uvāca", "bhūya eva mahā-bāho śṛṇu me paramaṃ vacaḥ", "yat te 'haṃ prīyamāṇāya vakṣyāmi hita-kāmyayā"], "rojas": [1, 2], "t": "<span class=\"vt-parte voz-krsna\">Escucha todavía, oh <a class=\"t\" href=\"glosario.html#mahabaho\" data-t=\"mahabaho\">Mahābāhu</a>, mi palabra suprema, que te diré a ti, que la recibes con gusto, porque deseo tu bien.</span>", "palabras": [{"iast": "śrī-bhagavān", "sa": "श्रीभगवान्", "gram": "nom. sg. m. comp.", "es": "el glorioso Señor", "ref": "bhagavan", "analisis": "śrī (gloria) + bhagavat (el Señor)"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "bhūyaḥ", "sa": "भूयः", "gram": "adv.", "es": "de nuevo, todavía más"}, {"iast": "eva", "sa": "एव", "gram": "partícula", "es": "en verdad (refuerzo)"}, {"iast": "mahā-bāho", "sa": "महाबाहो", "gram": "voc. sg. m. comp.", "es": "oh Mahābāhu, el de los brazos poderosos", "ref": "mahabaho", "analisis": "mahat (grande) + bāhu (brazo)"}, {"iast": "śṛṇu", "sa": "शृणु", "gram": "2 sg. imper.", "es": "escucha", "analisis": "√śru (oír)"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "mi"}, {"iast": "paramam", "sa": "परमम्", "gram": "ac. sg. n.", "es": "suprema"}, {"iast": "vacaḥ", "sa": "वचः", "gram": "ac. sg. n.", "es": "palabra", "analisis": "√vac (hablar)"}, {"iast": "yat", "sa": "यत्", "gram": "ac. sg. n. rel.", "es": "la que"}, {"iast": "te", "sa": "ते", "gram": "dat. sg. pron.", "es": "a ti"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "prīyamāṇāya", "sa": "प्रीयमाणाय", "gram": "dat. sg. m. part. pres. med.", "es": "que te complaces, que la recibes con gusto", "analisis": "√prī (agradar, complacerse)"}, {"iast": "vakṣyāmi", "sa": "वक्ष्यामि", "gram": "1 sg. fut.", "es": "diré", "analisis": "√vac (hablar)"}, {"iast": "hita-kāmyayā", "sa": "हितकाम्यया", "gram": "instr. sg. f. comp.", "es": "por deseo de tu bien", "analisis": "hita (bien, provecho) + kāmyā (deseo)"}], "nota": "<p><em>Bhūya eva</em>, «de nuevo, todavía»: Kṛṣṇa retoma lo que venía diciendo en los capítulos 7 y 9, el conocimiento de su naturaleza, y anuncia que lo ampliará. <em>Prīyamāṇa</em> es el que se complace o se deleita: Arjuna escucha con gusto, y por eso se le puede seguir hablando. <em>Hita-kāmyayā</em>, «por deseo de tu bien»: la enseñanza no es una exhibición, sino un servicio al que escucha.</p>", "interp": [{"titulo": "Un capítulo que nace de la escucha", "html": "<p>El capítulo 10 continúa sin pausa el 9: allí terminaba con la invitación «ten la mente en mí» (<a class=\"vref\" href=\"capitulo-09.html#v34\" data-v=\"9.34\">9.34</a>), y aquí Kṛṣṇa vuelve a hablar porque ve en Arjuna el gusto de escuchar. La primera parte del capítulo (<a class=\"vref\" href=\"capitulo-10.html#v1\" data-v=\"10.1\">10.1</a>–<a class=\"vref\" href=\"capitulo-10.html#v11\" data-v=\"10.11\">10.11</a>) es de Kṛṣṇa; luego Arjuna pregunta por las manifestaciones divinas (<a class=\"vref\" href=\"capitulo-10.html#v12\" data-v=\"10.12\">10.12</a>–<a class=\"vref\" href=\"capitulo-10.html#v18\" data-v=\"10.18\">10.18</a>), y el resto es la respuesta.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 2, "hablante": "krsna", "sa": ["न मे विदुः सुरगणाः प्रभवं न महर्षयः ।", "अहमादिर्हि देवानां महर्षीणां च सर्वशः ॥२॥"], "iast": ["na me viduḥ sura-gaṇāḥ prabhavaṃ na maharṣayaḥ", "aham ādir hi devānāṃ maharṣīṇāṃ ca sarvaśaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Ni las huestes de los <a class=\"t\" href=\"glosario.html#deva\" data-t=\"deva\">dioses</a> ni los grandes <a class=\"t\" href=\"glosario.html#rsi\" data-t=\"rsi\">sabios</a> conocen mi origen; porque yo soy, en todo, el principio de los dioses y de los grandes sabios.</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "partícula", "es": "no"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "mi"}, {"iast": "viduḥ", "sa": "विदुः", "gram": "3 pl. pf. (con sentido de presente)", "es": "conocen", "analisis": "√vid (saber)"}, {"iast": "sura-gaṇāḥ", "sa": "सुरगणाः", "gram": "nom. pl. m. comp.", "es": "las huestes de los dioses", "ref": "deva", "analisis": "sura (dios) + gaṇa (multitud)"}, {"iast": "prabhavam", "sa": "प्रभवम्", "gram": "ac. sg. m.", "es": "origen", "analisis": "pra-√bhū (surgir, nacer)"}, {"iast": "maharṣayaḥ", "sa": "महर्षयः", "gram": "nom. pl. m. comp.", "es": "los grandes sabios", "ref": "rsi", "analisis": "mahat (grande) + ṛṣi (vidente)"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "ādiḥ", "sa": "आदिः", "gram": "nom. sg. m.", "es": "el principio"}, {"iast": "hi", "sa": "हि", "gram": "partícula", "es": "porque"}, {"iast": "devānām", "sa": "देवानाम्", "gram": "gen. pl. m.", "es": "de los dioses", "ref": "deva"}, {"iast": "maharṣīṇām", "sa": "महर्षीणाम्", "gram": "gen. pl. m.", "es": "de los grandes sabios", "ref": "rsi"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "sarvaśaḥ", "sa": "सर्वशः", "gram": "adv.", "es": "en todos los sentidos, de todos ellos"}], "nota": "<p><em>Prabhava</em> es «origen, nacimiento»; con una sola letra más, <em>prabhāva</em> es «poder, grandeza», y la tradición ha jugado con las dos palabras (véase la alternativa). El argumento es sencillo: lo que es anterior a los dioses y a los sabios no puede ser conocido por ellos desde fuera, como no conoce el hijo el nacimiento de su padre. <em>Sarvaśaḥ</em>, «en todos los sentidos»: no sólo los precede, sino que es su causa en todo.</p>", "interp": [{"titulo": "Nadie conoce su origen", "html": "<p>El verso retoma lo dicho en <a class=\"vref\" href=\"capitulo-07.html#v26\" data-v=\"7.26\">7.26</a> («a mí nadie me conoce») y en <a class=\"vref\" href=\"capitulo-04.html#v5\" data-v=\"4.5\">4.5</a>, donde Kṛṣṇa conoce sus muchos nacimientos y Arjuna no. Ahora la ignorancia alcanza también a los dioses y a los sabios. Arjuna lo repetirá con sus palabras en <a class=\"vref\" href=\"capitulo-10.html#v14\" data-v=\"10.14\">10.14</a>: ni los dioses ni los demonios conocen su manifestación.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Ni las huestes de los dioses ni los grandes sabios conocen mi grandeza; porque yo soy, en todo, el principio de los dioses y de los grandes sabios.", "nota": "<p>Leyendo <em>prabhava</em> con el sentido de <em>prabhāva</em>, «poder, grandeza soberana», como <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> y, en primer lugar, <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, que dan también la glosa «origen». La traducción principal toma el sentido directo de la palabra, «origen», que es el que justifica la segunda mitad: si él es el principio de los dioses, éstos no pueden conocer su origen.</p>"}], "ens": "todo-procede-de-el"}, {"n": 3, "hablante": "krsna", "sa": ["यो मामजमनादिं च वेत्ति लोकमहेश्वरम् ।", "असम्मूढः स मर्त्येषु सर्वपापैः प्रमुच्यते ॥३॥"], "iast": ["yo mām ajam anādiṃ ca vetti loka-maheśvaram", "asammūḍhaḥ sa martyeṣu sarva-pāpaiḥ pramucyate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Quien me conoce no nacido y sin principio, <a class=\"t\" href=\"glosario.html#mahesvara\" data-t=\"mahesvara\">gran Señor de los mundos</a>, ése, libre de extravío entre los mortales, queda libre de todo <a class=\"t\" href=\"glosario.html#papa\" data-t=\"papa\">pecado</a>.</span>", "palabras": [{"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. rel.", "es": "quien"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}, {"iast": "ajam", "sa": "अजम्", "gram": "ac. sg. m.", "es": "no nacido", "analisis": "a- (no) + √jan (nacer)"}, {"iast": "anādim", "sa": "अनादिम्", "gram": "ac. sg. m.", "es": "sin principio", "analisis": "an- (no) + ādi (principio)"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "vetti", "sa": "वेत्ति", "gram": "3 sg. pres.", "es": "conoce", "analisis": "√vid (saber)"}, {"iast": "loka-maheśvaram", "sa": "लोकमहेश्वरम्", "gram": "ac. sg. m. comp.", "es": "gran Señor de los mundos", "ref": "mahesvara", "analisis": "loka (mundo) + mahā (grande) + īśvara (señor)"}, {"iast": "asammūḍhaḥ", "sa": "असम्मूढः", "gram": "nom. sg. m.", "es": "no extraviado", "ref": "moha", "analisis": "a- (no) + sam-√muh (extraviarse)"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "él"}, {"iast": "martyeṣu", "sa": "मर्त्येषु", "gram": "loc. pl. m.", "es": "entre los mortales", "analisis": "√mṛ (morir)"}, {"iast": "sarva-pāpaiḥ", "sa": "सर्वपापैः", "gram": "instr./abl. pl. n. comp.", "es": "de todos los pecados", "ref": "papa", "analisis": "sarva (todo) + pāpa (pecado)"}, {"iast": "pramucyate", "sa": "प्रमुच्यते", "gram": "3 sg. pres. pas.", "es": "queda libre", "analisis": "pra-√muc (soltar, liberar)"}], "nota": "<p><em>Ajam anādiṃ ca</em>: «no nacido» y «sin principio» parecen decir lo mismo, pero el segundo va más lejos: no sólo no ha nacido, sino que nada lo precede. Es la respuesta al verso anterior: los dioses y los sabios tienen un principio, que es él; él no lo tiene. <em>Asammūḍha</em>, «libre de extravío», es lo contrario del <em>mūḍha</em>, el «necio» que lo desprecia en forma humana (<a class=\"vref\" href=\"capitulo-09.html#v11\" data-v=\"9.11\">9.11</a>). <em>Loka-maheśvara</em> repite, sin <em>sarva-</em>, el título de <a class=\"vref\" href=\"capitulo-05.html#v29\" data-v=\"5.29\">5.29</a> (<em>sarva-loka-maheśvara</em>).</p>", "interp": [{"titulo": "Conocer quién es basta", "html": "<p>El fruto que el verso promete, quedar libre de todo pecado, no se atribuye aquí a una práctica, sino a un conocimiento: saber quién es Kṛṣṇa. Es la misma lógica de <a class=\"vref\" href=\"capitulo-04.html#v9\" data-v=\"4.9\">4.9</a> (quien conoce su nacimiento y su obra divinos no vuelve a nacer) y de <a class=\"vref\" href=\"capitulo-09.html#v1\" data-v=\"9.1\">9.1</a>.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "todo-procede-de-el"}, {"n": 4, "hablante": "krsna", "sa": ["बुद्धिर्ज्ञानमसम्मोहः क्षमा सत्यं दमः शमः ।", "सुखं दुःखं भवोऽभावो भयं चाभयमेव च ॥४॥"], "iast": ["buddhir jñānam asammohaḥ kṣamā satyaṃ damaḥ śamaḥ", "sukhaṃ duḥkhaṃ bhavo 'bhāvo bhayaṃ cābhayam eva ca"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">El <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a>, el <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a>, la ausencia de <a class=\"t\" href=\"glosario.html#moha\" data-t=\"moha\">extravío</a>, la paciencia, la verdad, el dominio de los sentidos, la calma, el <a class=\"t\" href=\"glosario.html#sukha\" data-t=\"sukha\">placer</a> y el <a class=\"t\" href=\"glosario.html#duhkha\" data-t=\"duhkha\">dolor</a>, el nacer y el dejar de ser, el miedo y también el valor,</span>", "palabras": [{"iast": "buddhiḥ", "sa": "बुद्धिः", "gram": "nom. sg. f.", "es": "el entendimiento", "ref": "buddhi"}, {"iast": "jñānam", "sa": "ज्ञानम्", "gram": "nom. sg. n.", "es": "el conocimiento", "ref": "jnana"}, {"iast": "asammohaḥ", "sa": "असम्मोहः", "gram": "nom. sg. m.", "es": "la ausencia de extravío", "ref": "moha", "analisis": "a- (no) + sammoha (extravío)"}, {"iast": "kṣamā", "sa": "क्षमा", "gram": "nom. sg. f.", "es": "la paciencia, el perdón"}, {"iast": "satyam", "sa": "सत्यम्", "gram": "nom. sg. n.", "es": "la verdad, la veracidad"}, {"iast": "damaḥ", "sa": "दमः", "gram": "nom. sg. m.", "es": "el dominio (de los sentidos)", "analisis": "√dam (domar)"}, {"iast": "śamaḥ", "sa": "शमः", "gram": "nom. sg. m.", "es": "la calma (de la mente)", "analisis": "√śam (calmarse)"}, {"iast": "sukham", "sa": "सुखम्", "gram": "nom. sg. n.", "es": "el placer", "ref": "sukha"}, {"iast": "duḥkham", "sa": "दुःखम्", "gram": "nom. sg. n.", "es": "el dolor", "ref": "duhkha"}, {"iast": "bhavaḥ", "sa": "भवः", "gram": "nom. sg. m.", "es": "el nacer, el llegar a ser", "analisis": "√bhū (ser, llegar a ser)"}, {"iast": "abhāvaḥ", "sa": "अभावः", "gram": "nom. sg. m.", "es": "el dejar de ser", "analisis": "a- (no) + bhāva (ser)"}, {"iast": "bhayam", "sa": "भयम्", "gram": "nom. sg. n.", "es": "el miedo"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "abhayam", "sa": "अभयम्", "gram": "nom. sg. n.", "es": "la ausencia de miedo, el valor"}, {"iast": "eva", "sa": "एव", "gram": "partícula", "es": "también"}], "nota": "<p>Los versos 4 y 5 forman una sola frase: una lista de veinte disposiciones de los seres, que el verso 5 cierra diciendo que todas nacen de Kṛṣṇa. <em>Dama</em> y <em>śama</em> se distinguen en <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>: <em>dama</em> es el dominio de los sentidos externos, <em>śama</em> la calma de la mente. <em>Bhava</em> y <em>abhāva</em> pueden entenderse como el surgir y su contrario, el nacimiento y la muerte (<a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>; <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> propone también «el ser y el no ser»), o, con <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, como el ánimo que se eleva ante lo grato y el que decae ante lo adverso; la traducción conserva el sentido más general, «nacer y dejar de ser».</p>", "interp": [{"titulo": "También lo que duele", "html": "<p>La lista no se limita a las virtudes: junto al entendimiento, la verdad y la calma aparecen el dolor, la muerte y el miedo. La Gītā no reparte el mundo entre un principio del bien y otro del mal; todas las disposiciones de los seres, las gratas y las ingratas, proceden de la misma fuente. Es la idea de <a class=\"vref\" href=\"capitulo-07.html#v12\" data-v=\"7.12\">7.12</a>: los estados que nacen de las tres guṇas proceden de él, aunque él no está en ellos.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "todo-procede-de-el"}, {"n": 5, "hablante": "krsna", "sa": ["अहिंसा समता तुष्टिस्तपो दानं यशोऽयशः ।", "भवन्ति भावा भूतानां मत्त एव पृथग्विधाः ॥५॥"], "iast": ["ahiṃsā samatā tuṣṭis tapo dānaṃ yaśo 'yaśaḥ", "bhavanti bhāvā bhūtānāṃ matta eva pṛthag-vidhāḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">la <a class=\"t\" href=\"glosario.html#ahimsa\" data-t=\"ahimsa\">no-violencia</a>, la <a class=\"t\" href=\"glosario.html#samatva\" data-t=\"samatva\">ecuanimidad</a>, el contento, la <a class=\"t\" href=\"glosario.html#tapas\" data-t=\"tapas\">austeridad</a>, el dar, la <a class=\"t\" href=\"glosario.html#kirti\" data-t=\"kirti\">fama</a> y la infamia: estas disposiciones de los seres, en toda su diversidad, nacen sólo de mí.</span>", "palabras": [{"iast": "ahiṃsā", "sa": "अहिंसा", "gram": "nom. sg. f.", "es": "la no-violencia", "ref": "ahimsa", "analisis": "a- (no) + hiṃsā (daño)"}, {"iast": "samatā", "sa": "समता", "gram": "nom. sg. f.", "es": "la ecuanimidad", "ref": "samatva", "analisis": "sama (igual) + -tā"}, {"iast": "tuṣṭiḥ", "sa": "तुष्टिः", "gram": "nom. sg. f.", "es": "el contento", "analisis": "√tuṣ (estar satisfecho)"}, {"iast": "tapaḥ", "sa": "तपः", "gram": "nom. sg. n.", "es": "la austeridad", "ref": "tapas"}, {"iast": "dānam", "sa": "दानम्", "gram": "nom. sg. n.", "es": "el dar, la generosidad", "analisis": "√dā (dar)"}, {"iast": "yaśaḥ", "sa": "यशः", "gram": "nom. sg. n.", "es": "la fama", "ref": "kirti"}, {"iast": "ayaśaḥ", "sa": "अयशः", "gram": "nom. sg. n.", "es": "la infamia", "analisis": "a- (no) + yaśas (fama)"}, {"iast": "bhavanti", "sa": "भवन्ति", "gram": "3 pl. pres.", "es": "son, surgen", "analisis": "√bhū (ser)"}, {"iast": "bhāvāḥ", "sa": "भावाः", "gram": "nom. pl. m.", "es": "los estados, las disposiciones", "analisis": "√bhū (ser)"}, {"iast": "bhūtānām", "sa": "भूतानाम्", "gram": "gen. pl. n.", "es": "de los seres", "analisis": "√bhū (ser)"}, {"iast": "mattaḥ", "sa": "मत्तः", "gram": "abl. sg. pron.", "es": "de mí"}, {"iast": "eva", "sa": "एव", "gram": "partícula", "es": "sólo"}, {"iast": "pṛthag-vidhāḥ", "sa": "पृथग्विधाः", "gram": "nom. pl. m. comp.", "es": "de diversas clases", "analisis": "pṛthak (separadamente) + vidhā (clase)"}], "nota": "<p><em>Bhāva</em> es aquí «estado, disposición»: el modo de ser que se da en cada ser. <em>Matta eva</em>, «sólo de mí», cierra la enumeración de los dos versos. <em>Yaśas</em> y <em>ayaśas</em> son la buena y la mala fama. Varias de estas cualidades reaparecen en la lista de las «virtudes divinas» de <a class=\"vref\" href=\"capitulo-16.html#v1\" data-v=\"16.1\">16.1</a>–<a class=\"vref\" href=\"capitulo-16.html#v3\" data-v=\"16.3\">16.3</a> y en la del conocimiento de <a class=\"vref\" href=\"capitulo-13.html#v7\" data-v=\"13.7\">13.7</a>–<a class=\"vref\" href=\"capitulo-13.html#v11\" data-v=\"13.11\">13.11</a>.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "todo-procede-de-el"}, {"n": 6, "hablante": "krsna", "sa": ["महर्षयः सप्त पूर्वे चत्वारो मनवस्तथा ।", "मद्भावा मानसा जाता येषां लोक इमाः प्रजाः ॥६॥"], "iast": ["maharṣayaḥ sapta pūrve catvāro manavas tathā", "mad-bhāvā mānasā jātā yeṣāṃ loka imāḥ prajāḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Los siete grandes <a class=\"t\" href=\"glosario.html#saptarsi\" data-t=\"saptarsi\">sabios</a> antiguos y, así también, los cuatro <a class=\"t\" href=\"glosario.html#manu\" data-t=\"manu\">Manus</a>, que tienen de mí su ser, nacieron de mi <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a>; de ellos proceden las criaturas de este mundo.</span>", "palabras": [{"iast": "maharṣayaḥ", "sa": "महर्षयः", "gram": "nom. pl. m. comp.", "es": "los grandes sabios", "ref": "saptarsi", "analisis": "mahat (grande) + ṛṣi (vidente)"}, {"iast": "sapta", "sa": "सप्त", "gram": "nom. num.", "es": "siete"}, {"iast": "pūrve", "sa": "पूर्वे", "gram": "nom. pl. m.", "es": "antiguos, primeros"}, {"iast": "catvāraḥ", "sa": "चत्वारः", "gram": "nom. pl. m. num.", "es": "cuatro"}, {"iast": "manavaḥ", "sa": "मनवः", "gram": "nom. pl. m.", "es": "los Manus", "ref": "manu"}, {"iast": "tathā", "sa": "तथा", "gram": "adv.", "es": "así también"}, {"iast": "mad-bhāvāḥ", "sa": "मद्भावाः", "gram": "nom. pl. m. comp.", "es": "que tienen su ser de mí, partícipes de mi poder", "analisis": "mad (de mí) + bhāva (ser, estado)"}, {"iast": "mānasāḥ", "sa": "मानसाः", "gram": "nom. pl. m.", "es": "nacidos de la mente", "ref": "manas", "analisis": "manas (mente) + -a"}, {"iast": "jātāḥ", "sa": "जाताः", "gram": "nom. pl. m. part. pas.", "es": "nacidos", "analisis": "√jan (nacer)"}, {"iast": "yeṣām", "sa": "येषाम्", "gram": "gen. pl. m. rel.", "es": "de los cuales"}, {"iast": "loke", "sa": "लोके", "gram": "loc. sg. m.", "es": "en el mundo"}, {"iast": "imāḥ", "sa": "इमाः", "gram": "nom. pl. f. pron.", "es": "estas"}, {"iast": "prajāḥ", "sa": "प्रजाः", "gram": "nom. pl. f.", "es": "criaturas, descendencia", "analisis": "pra-√jan (engendrar)"}], "nota": "<p><em>Mānasa</em>, «nacido de la mente»: en los relatos de la creación, los primeros sabios y progenitores no nacen de un vientre, sino del pensamiento del creador. <em>Mad-bhāva</em>, «cuyo ser viene de mí» o «que participan de mi naturaleza»; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo entienden «con el pensamiento puesto en mí», y por ello dotados de su poder; <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, «en quienes está mi poder»; <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, «que siguen mi voluntad». Los siete grandes sabios son los progenitores de los linajes (véase la ficha <a class=\"t\" href=\"glosario.html#saptarsi\" data-t=\"saptarsi\">saptarṣi</a>); los Manus, los padres de la humanidad en cada período del mundo (ficha <a class=\"t\" href=\"glosario.html#manu\" data-t=\"manu\">Manu</a>). <em>Pūrve</em>, «antiguos», puede ir con los siete sabios o abrir un grupo propio: de eso depende cómo se lea el número cuatro (véase la alternativa).</p>", "interp": [{"titulo": "Los padres de los padres", "html": "<p>El verso aplica a los progenitores lo que el anterior dijo de las disposiciones: también los primeros padres de las criaturas, los que las tradiciones ponen al principio de los linajes, nacen de Kṛṣṇa. Así se cierra el argumento de <a class=\"vref\" href=\"capitulo-10.html#v2\" data-v=\"10.2\">10.2</a>: los grandes sabios no conocen su origen porque él es el origen de ellos.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Los siete grandes sabios, los cuatro antiguos y, así también, los Manus, que tienen de mí su ser, nacieron de mi mente; de ellos proceden las criaturas de este mundo.", "nota": "<p>Separando <em>pūrve catvāraḥ</em>, «los cuatro antiguos», de <em>manavaḥ</em>, «los Manus». Así lo leen <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, los gauḍīyas Viśvanātha Cakravartī y Prabhupāda y, como segunda lectura, <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, que ven en los cuatro antiguos a Sanaka y sus hermanos, los sabios eternamente jóvenes nacidos de la mente de Brahmā. La traducción principal sigue la lectura de <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> y <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, que entienden «los cuatro Manus»; véase la ficha <a class=\"t\" href=\"glosario.html#manu\" data-t=\"manu\">Manu</a>.</p>"}], "ens": "todo-procede-de-el"}, {"n": 7, "hablante": "krsna", "sa": ["एतां विभूतिं योगं च मम यो वेत्ति तत्त्वतः ।", "सोऽविकम्पेन योगेन युज्यते नात्र संशयः ॥७॥"], "iast": ["etāṃ vibhūtiṃ yogaṃ ca mama yo vetti tattvataḥ", "so 'vikampena yogena yujyate nātra saṃśayaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Quien conoce de verdad esta <a class=\"t\" href=\"glosario.html#vibhuti\" data-t=\"vibhuti\">manifestación</a> mía y mi <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a> se une con un yoga inquebrantable: no hay en ello <a class=\"t\" href=\"glosario.html#samsaya\" data-t=\"samsaya\">duda</a>.</span>", "palabras": [{"iast": "etām", "sa": "एताम्", "gram": "ac. sg. f. pron.", "es": "esta"}, {"iast": "vibhūtim", "sa": "विभूतिम्", "gram": "ac. sg. f.", "es": "manifestación, despliegue de poder", "ref": "vibhuti", "analisis": "vi-√bhū (manifestarse, desplegarse)"}, {"iast": "yogam", "sa": "योगम्", "gram": "ac. sg. m.", "es": "yoga, poder", "ref": "yoga"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "mama", "sa": "मम", "gram": "gen. sg. pron.", "es": "mi"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. rel.", "es": "quien"}, {"iast": "vetti", "sa": "वेत्ति", "gram": "3 sg. pres.", "es": "conoce", "analisis": "√vid (saber)"}, {"iast": "tattvataḥ", "sa": "तत्त्वतः", "gram": "adv.", "es": "de verdad, en su realidad", "analisis": "tattva (realidad) + -tas"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "él"}, {"iast": "avikampena", "sa": "अविकम्पेन", "gram": "instr. sg. m.", "es": "inquebrantable, que no vacila", "analisis": "a- (no) + vi-√kamp (temblar)"}, {"iast": "yogena", "sa": "योगेन", "gram": "instr. sg. m.", "es": "con un yoga", "ref": "yoga"}, {"iast": "yujyate", "sa": "युज्यते", "gram": "3 sg. pres. pas.", "es": "se une", "analisis": "√yuj (uncir, unir)"}, {"iast": "na", "sa": "न", "gram": "partícula", "es": "no"}, {"iast": "atra", "sa": "अत्र", "gram": "adv.", "es": "en esto"}, {"iast": "saṃśayaḥ", "sa": "संशयः", "gram": "nom. sg. m.", "es": "duda", "ref": "samsaya"}], "nota": "<p><em>Vibhūti</em>, de vi-√bhū, «extenderse, manifestarse con poder»: es la palabra que da nombre al capítulo, y aquí se refiere a lo dicho en los versos anteriores, que todo procede de Kṛṣṇa. <em>Yoga</em> tiene en la primera mitad el sentido de poder, como el «yoga soberano» de <a class=\"vref\" href=\"capitulo-09.html#v5\" data-v=\"9.5\">9.5</a>; en la segunda, el de la disciplina que une: el verso juega con los dos (véase la alternativa).</p>", "interp": [{"titulo": "Conocer el poder para unirse", "html": "<p>El verso enlaza los dos sentidos de la palabra <em>yoga</em>: quien conoce el yoga de Kṛṣṇa, su poder de manifestarse en todo, queda unido a él con un yoga que no vacila. El conocimiento de las manifestaciones no es erudición: es un camino de unión. Por eso Arjuna pedirá, en <a class=\"vref\" href=\"capitulo-10.html#v16\" data-v=\"10.16\">10.16</a>–<a class=\"vref\" href=\"capitulo-10.html#v18\" data-v=\"10.18\">10.18</a>, que se las enumere.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Quien conoce de verdad este despliegue de mi poder y mi capacidad de manifestarme se une con un yoga inquebrantable: no hay en ello duda.", "nota": "<p>Haciendo explícito el sentido que <em>vibhūti</em> y <em>yoga</em> tienen en la primera mitad: la <em>vibhūti</em> como el despliegue o la extensión del poder de Kṛṣṇa (<a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> la glosa <em>vistāra</em>, «extensión»), y el <em>yoga</em> como el poder mismo que la hace posible (así <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>; <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> entiende por <em>yoga</em> sus cualidades benditas), el «yoga soberano» de <a class=\"vref\" href=\"capitulo-09.html#v5\" data-v=\"9.5\">9.5</a>. La traducción principal deja las dos palabras como términos, enlazados a sus fichas. <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> las entiende de otro modo: la <em>vibhūti</em> es su señorío, el que todo dependa de él para nacer, durar y obrar; el <em>yoga</em>, la posesión de sus cualidades perfectas, opuestas a todo mal; y el yoga inquebrantable de la segunda mitad, la devoción (<em>bhakti-yoga</em>), como también para Viśvanātha Cakravartī.</p>"}], "ens": "todo-procede-de-el"}, {"n": 8, "hablante": "krsna", "sa": ["अहं सर्वस्य प्रभवो मत्तः सर्वं प्रवर्तते ।", "इति मत्वा भजन्ते मां बुधा भावसमन्विताः ॥८॥"], "iast": ["ahaṃ sarvasya prabhavo mattaḥ sarvaṃ pravartate", "iti matvā bhajante māṃ budhā bhāva-samanvitāḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Yo soy el origen de todo; de mí procede todo. Sabiéndolo, los sabios me <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">adoran</a> con el corazón lleno de amor.</span>", "palabras": [{"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "sarvasya", "sa": "सर्वस्य", "gram": "gen. sg. n.", "es": "de todo"}, {"iast": "prabhavaḥ", "sa": "प्रभवः", "gram": "nom. sg. m.", "es": "el origen", "analisis": "pra-√bhū (surgir)"}, {"iast": "mattaḥ", "sa": "मत्तः", "gram": "abl. sg. pron.", "es": "de mí"}, {"iast": "sarvam", "sa": "सर्वम्", "gram": "nom. sg. n.", "es": "todo"}, {"iast": "pravartate", "sa": "प्रवर्तते", "gram": "3 sg. pres. med.", "es": "procede, se pone en marcha", "analisis": "pra-√vṛt (moverse, proceder)"}, {"iast": "iti", "sa": "इति", "gram": "partícula", "es": "así (cierra lo pensado)"}, {"iast": "matvā", "sa": "मत्वा", "gram": "abs.", "es": "pensando, sabiendo", "analisis": "√man (pensar)"}, {"iast": "bhajante", "sa": "भजन्ते", "gram": "3 pl. pres. med.", "es": "adoran", "ref": "bhakti", "analisis": "√bhaj (participar, venerar)"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}, {"iast": "budhāḥ", "sa": "बुधाः", "gram": "nom. pl. m.", "es": "los sabios, los que comprenden", "analisis": "√budh (despertar, comprender)"}, {"iast": "bhāva-samanvitāḥ", "sa": "भावसमन्विताः", "gram": "nom. pl. m. comp.", "es": "llenos de sentimiento, con el corazón entregado", "analisis": "bhāva (estado de ánimo, sentimiento) + samanvita (dotado de)"}], "nota": "<p>Primero de los cuatro versos (10.8–10.11) que resumen el capítulo y que la tradición <a class=\"t\" href=\"glosario.html#gaudiya\" data-t=\"gaudiya\">gauḍīya</a> ha leído como el núcleo de toda la Gītā (véase la interpretación). <em>Bhāva</em>, que en <a class=\"vref\" href=\"capitulo-10.html#v5\" data-v=\"10.5\">10.5</a> era «disposición», es aquí el sentimiento del que ama (<em>prīti</em>, «afecto», en <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>; <em>prema</em>, «amor», en <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>; para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, en cambio, el fervor por la verdad suprema): <em>bhāva-samanvita</em>, «dotado de bhāva», es el que adora con el corazón, no sólo con el entendimiento. <em>Budha</em>, «el que ha despertado, el que comprende»: la devoción de este verso nace de un conocimiento, el de que todo procede de Kṛṣṇa.</p>", "interp": [{"titulo": "Del conocimiento a la devoción", "html": "<p>El verso une las dos mitades del capítulo 7 y del 9: el conocimiento de que Kṛṣṇa es el origen de todo (<a class=\"vref\" href=\"capitulo-07.html#v6\" data-v=\"7.6\">7.6</a>, <a class=\"vref\" href=\"capitulo-09.html#v18\" data-v=\"9.18\">9.18</a>) no termina en sí mismo, sino que se vuelve adoración. Los que lo saben «me adoran»: el saber y el amor no son dos caminos, sino dos momentos del mismo.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "Los cuatro versos esenciales", "html": "<p>En la tradición <a class=\"t\" href=\"glosario.html#gaudiya\" data-t=\"gaudiya\">gauḍīya</a>, los versos 10.8–10.11 se conocen como los cuatro versos esenciales de la Gītā (<em>catuḥ-ślokī</em>): así los llama Viśvanātha Cakravartī al final de su comentario a <a class=\"vref\" href=\"capitulo-10.html#v11\" data-v=\"10.11\">10.11</a>, y Prabhupāda habla de «los cuatro versos esenciales». Los gauḍīyas posteriores los comparan con los cuatro versos del <em>Bhāgavata Purāṇa</em> (2.9.32–35; 2.9.33–36 en las ediciones gauḍīyas) que el Señor enseña a Brahmā: en ellos se condensa el contenido de toda la obra, el origen de todo en Kṛṣṇa, la devoción que nace de saberlo y la gracia con que él responde.</p>", "trad": "gaudiya", "tradNombre": "Vaiṣṇavismo gauḍīya"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "pensar-en-el-y-hablar-de-el"}, {"n": 9, "hablante": "krsna", "sa": ["मच्चित्ता मद्गतप्राणा बोधयन्तः परस्परम् ।", "कथयन्तश्च मां नित्यं तुष्यन्ति च रमन्ति च ॥९॥"], "iast": ["mac-cittā mad-gata-prāṇā bodhayantaḥ parasparam", "kathayantaś ca māṃ nityaṃ tuṣyanti ca ramanti ca"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Con el <a class=\"t\" href=\"glosario.html#citta\" data-t=\"citta\">pensamiento</a> en mí, con la vida entregada a mí, iluminándose unos a otros y hablando siempre de mí, encuentran en ello su contento y su deleite.</span>", "palabras": [{"iast": "mac-cittāḥ", "sa": "मच्चित्ताः", "gram": "nom. pl. m. comp.", "es": "con el pensamiento en mí", "ref": "citta", "analisis": "mad (en mí) + citta (pensamiento)"}, {"iast": "mad-gata-prāṇāḥ", "sa": "मद्गतप्राणाः", "gram": "nom. pl. m. comp.", "es": "con la vida entregada a mí", "ref": "prana", "analisis": "mad (a mí) + gata (ido) + prāṇa (aliento vital, vida)"}, {"iast": "bodhayantaḥ", "sa": "बोधयन्तः", "gram": "nom. pl. m. part. pres. caus.", "es": "haciéndose comprender, iluminándose", "analisis": "√budh (despertar), causativo"}, {"iast": "parasparam", "sa": "परस्परम्", "gram": "adv.", "es": "unos a otros"}, {"iast": "kathayantaḥ", "sa": "कथयन्तः", "gram": "nom. pl. m. part. pres.", "es": "hablando de", "analisis": "√kath (contar, hablar)"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "de mí"}, {"iast": "nityam", "sa": "नित्यम्", "gram": "adv.", "es": "siempre"}, {"iast": "tuṣyanti", "sa": "तुष्यन्ति", "gram": "3 pl. pres.", "es": "se contentan", "analisis": "√tuṣ (estar satisfecho)"}, {"iast": "ramanti", "sa": "रमन्ति", "gram": "3 pl. pres.", "es": "se deleitan", "analisis": "√ram (gozar, deleitarse)"}], "nota": "<p><em>Mad-gata-prāṇa</em>, «cuyos <em>prāṇa</em> han ido a mí»: puede entenderse como «cuya vida está entregada a mí» o, tomando <em>prāṇa</em> en plural como las facultades vitales y los sentidos, «con los sentidos recogidos en mí» (véase la alternativa). <em>Bodhayantaḥ parasparam</em>, «haciéndose comprender unos a otros»: la devoción de este verso no es solitaria, sino compartida. <em>Tuṣyanti ca ramanti ca</em>: el contento y el deleite no son la recompensa futura de esta vida, sino lo que la acompaña.</p>", "interp": [{"titulo": "Una devoción en compañía", "html": "<p>El verso describe a los que adoran a Kṛṣṇa no sólo en su relación con él, sino entre ellos: se explican unos a otros lo que han comprendido y hablan de él sin cansarse. Es el retrato de una comunidad que se forma alrededor de la enseñanza, como la que pinta <a class=\"vref\" href=\"capitulo-09.html#v14\" data-v=\"9.14\">9.14</a> («glorificándome sin cesar»). La tradición india ha valorado mucho esta compañía de los que buscan lo mismo (<em>satsaṅga</em>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Con el pensamiento en mí, con los sentidos recogidos en mí, iluminándose unos a otros y hablando siempre de mí, encuentran en ello su contento y su deleite.", "nota": "<p>Tomando <em>prāṇa</em> en el sentido de las facultades vitales, los sentidos con que se vive, como hacen en primer lugar <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> («con los sentidos recogidos en mí»), <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, que dan también la otra lectura: los devotos los tienen recogidos en Kṛṣṇa, sin dispersarse en los objetos. La traducción principal toma <em>prāṇa</em> como la vida misma, entregada a él, como <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> y Viśvanātha Cakravartī: los devotos no pueden sostener la vida sin Kṛṣṇa.</p>"}], "ens": "pensar-en-el-y-hablar-de-el"}, {"n": 10, "hablante": "krsna", "sa": ["तेषां सततयुक्तानां भजतां प्रीतिपूर्वकम् ।", "ददामि बुद्धियोगं तं येन मामुपयान्ति ते ॥१०॥"], "iast": ["teṣāṃ satata-yuktānāṃ bhajatāṃ prīti-pūrvakam", "dadāmi buddhi-yogaṃ taṃ yena mām upayānti te"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">A ellos, siempre <a class=\"t\" href=\"glosario.html#yukta\" data-t=\"yukta\">unidos</a> a mí, que me <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">adoran</a> con amor, les doy ese <a class=\"t\" href=\"glosario.html#buddhi-yoga\" data-t=\"buddhi-yoga\">yoga del entendimiento</a> por el que llegan a mí.</span>", "palabras": [{"iast": "teṣām", "sa": "तेषाम्", "gram": "dat./gen. pl. m. pron.", "es": "a ellos"}, {"iast": "satata-yuktānām", "sa": "सततयुक्तानाम्", "gram": "dat./gen. pl. m. comp.", "es": "siempre unidos", "ref": "yukta", "analisis": "satata (siempre) + yukta (unido)"}, {"iast": "bhajatām", "sa": "भजताम्", "gram": "dat./gen. pl. m. part. pres.", "es": "que adoran", "ref": "bhakti", "analisis": "√bhaj (venerar)"}, {"iast": "prīti-pūrvakam", "sa": "प्रीतिपूर्वकम्", "gram": "adv. comp.", "es": "con amor", "analisis": "prīti (amor, afecto) + pūrvaka (precedido de)"}, {"iast": "dadāmi", "sa": "ददामि", "gram": "1 sg. pres.", "es": "doy", "analisis": "√dā (dar)"}, {"iast": "buddhi-yogam", "sa": "बुद्धियोगम्", "gram": "ac. sg. m. comp.", "es": "el yoga del entendimiento", "ref": "buddhi-yoga", "analisis": "buddhi (entendimiento) + yoga"}, {"iast": "tam", "sa": "तम्", "gram": "ac. sg. m. pron.", "es": "ese"}, {"iast": "yena", "sa": "येन", "gram": "instr. sg. m. rel.", "es": "por el cual"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}, {"iast": "upayānti", "sa": "उपयान्ति", "gram": "3 pl. pres.", "es": "llegan", "analisis": "upa-√yā (acercarse, llegar)"}, {"iast": "te", "sa": "ते", "gram": "nom. pl. m. pron.", "es": "ellos"}], "nota": "<p>El <a class=\"t\" href=\"glosario.html#buddhi-yoga\" data-t=\"buddhi-yoga\">yoga del entendimiento</a> lleva el mismo nombre que el que Kṛṣṇa enseñó en <a class=\"vref\" href=\"capitulo-02.html#v39\" data-v=\"2.39\">2.39</a>–<a class=\"vref\" href=\"capitulo-02.html#v53\" data-v=\"2.53\">2.53</a> y nombró en <a class=\"vref\" href=\"capitulo-02.html#v49\" data-v=\"2.49\">2.49</a>: allí se presentaba como una disciplina que Arjuna debía adquirir; aquí, como un don que Kṛṣṇa concede a quienes lo aman. <em>Prīti-pūrvakam</em>, «precedido de amor», «con afecto»: lo que se pide primero no es la disciplina, sino el amor, y la disciplina llega como respuesta. <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> y Vedānta Deśika construyen en cambio <em>prīti-pūrvakam</em> con «doy»: es Kṛṣṇa quien da con amor ese yoga.</p>", "interp": [{"titulo": "La disciplina como don", "html": "<p>El verso invierte el orden que podía esperarse: no es que el devoto alcance el entendimiento recto y luego llegue a Kṛṣṇa, sino que Kṛṣṇa da el entendimiento a quien ya lo ama. La idea vuelve en <a class=\"vref\" href=\"capitulo-18.html#v57\" data-v=\"18.57\">18.57</a>, donde Kṛṣṇa pide a Arjuna que se apoye en el yoga del entendimiento con la mente puesta en él.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "A ellos, siempre unidos a mí, que me adoran con amor, les doy ese recto entendimiento por el que llegan a mí.", "nota": "<p>Entendiendo <em>buddhi-yoga</em> no como el nombre de la disciplina del capítulo 2, sino como «la unión con el recto entendimiento», el conocimiento verdadero de Kṛṣṇa: así lo glosan <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> (<em>samyag-darśana</em>, «la visión recta» de su naturaleza), y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> lo llama «conocimiento recto» (<em>samyag-jñāna</em>). La traducción principal conserva el término técnico, que enlaza este verso con <a class=\"vref\" href=\"capitulo-02.html#v49\" data-v=\"2.49\">2.49</a> y <a class=\"vref\" href=\"capitulo-18.html#v57\" data-v=\"18.57\">18.57</a>. También <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lo toma así: Kṛṣṇa da «ese mismo yoga del entendimiento», ya maduro; para Viśvanātha Cakravartī y Prabhupāda, de la tradición <a class=\"t\" href=\"glosario.html#gaudiya\" data-t=\"gaudiya\">gauḍīya</a>, es la devoción misma (<em>bhakti-yoga</em>).</p>"}], "ens": "la-lampara-del-conocimiento"}, {"n": 11, "hablante": "krsna", "sa": ["तेषामेवानुकम्पार्थमहमज्ञानजं तमः ।", "नाशयाम्यात्मभावस्थो ज्ञानदीपेन भास्वता ॥११॥"], "iast": ["teṣām evānukampārtham aham ajñāna-jaṃ tamaḥ", "nāśayāmy ātma-bhāva-stho jñāna-dīpena bhāsvatā"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Por compasión hacia ellos, yo, morando en su interior, disipo la oscuridad nacida de la <a class=\"t\" href=\"glosario.html#ajnana\" data-t=\"ajnana\">ignorancia</a> con la lámpara luminosa del <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a>.</span>", "palabras": [{"iast": "teṣām", "sa": "तेषाम्", "gram": "gen. pl. m. pron.", "es": "de ellos"}, {"iast": "eva", "sa": "एव", "gram": "partícula", "es": "precisamente"}, {"iast": "anukampārtham", "sa": "अनुकम्पार्थम्", "gram": "adv. comp.", "es": "por compasión", "analisis": "anukampā (compasión) + artha (fin)"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "ajñāna-jam", "sa": "अज्ञानजम्", "gram": "ac. sg. n. comp.", "es": "nacida de la ignorancia", "ref": "ajnana", "analisis": "ajñāna (ignorancia) + ja (nacido)"}, {"iast": "tamaḥ", "sa": "तमः", "gram": "ac. sg. n.", "es": "la oscuridad", "ref": "tamas"}, {"iast": "nāśayāmi", "sa": "नाशयामि", "gram": "1 sg. pres. caus.", "es": "destruyo, disipo", "analisis": "√naś (perecer), causativo"}, {"iast": "ātma-bhāva-sthaḥ", "sa": "आत्मभावस्थः", "gram": "nom. sg. m. comp.", "es": "morando en su interior", "ref": "atman", "analisis": "ātman (sí-mismo) + bhāva (ser, estado) + stha (que está)"}, {"iast": "jñāna-dīpena", "sa": "ज्ञानदीपेन", "gram": "instr. sg. m. comp.", "es": "con la lámpara del conocimiento", "ref": "jnana", "analisis": "jñāna (conocimiento) + dīpa (lámpara)"}, {"iast": "bhāsvatā", "sa": "भास्वता", "gram": "instr. sg. m.", "es": "luminosa, resplandeciente", "analisis": "√bhās (brillar)"}], "nota": "<p><em>Anukampā</em>, «compasión», literalmente «temblar con» el otro: la gracia de este verso no es un premio, sino una respuesta al amor del verso anterior. <em>Ātma-bhāva-sthaḥ</em>, «estando en el <em>ātma-bhāva</em>», puede entenderse como «morando en su ser interior», en el corazón de los devotos, o como «permaneciendo en mi propio ser», sin dejar su naturaleza; la primera es la de <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> y Viśvanātha Cakravartī, y Vedānta Deśika descarta expresamente la segunda. <em>Tamas</em> es aquí la oscuridad, no la guṇa: la ignorancia es tiniebla, y el conocimiento, una lámpara.</p>", "interp": [{"titulo": "La lámpara", "html": "<p>La Gītā ha usado varias imágenes de luz para el conocimiento: el sol que ilumina lo supremo (<a class=\"vref\" href=\"capitulo-05.html#v16\" data-v=\"5.16\">5.16</a>), el fuego que reduce a cenizas las acciones (<a class=\"vref\" href=\"capitulo-04.html#v37\" data-v=\"4.37\">4.37</a>). Aquí la imagen es más íntima: una lámpara encendida dentro, por el mismo Kṛṣṇa, en el corazón de quien lo ama. Lo que disipa no es una falta de datos, sino una oscuridad que nace de la ignorancia.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "la-lampara-del-conocimiento"}, {"n": 12, "hablante": "arjuna", "sa": ["अर्जुन उवाच ।", "परं ब्रह्म परं धाम पवित्रं परमं भवान् ।", "पुरुषं शाश्वतं दिव्यमादिदेवमजं विभुम् ॥१२॥"], "iast": ["arjuna uvāca", "paraṃ brahma paraṃ dhāma pavitraṃ paramaṃ bhavān", "puruṣaṃ śāśvataṃ divyam ādi-devam ajaṃ vibhum"], "rojas": [], "t": "<span class=\"vt-parte\">Tú eres el <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a> supremo, la morada suprema, el purificador supremo. A ti, la <a class=\"t\" href=\"glosario.html#purusa\" data-t=\"purusa\">Persona</a> eterna, divina, el dios primero, el no nacido, el que todo lo <a class=\"t\" href=\"glosario.html#vibhu\" data-t=\"vibhu\">penetra</a>,</span>", "palabras": [{"iast": "arjunaḥ", "sa": "अर्जुनः", "gram": "nom. sg. m.", "es": "Arjuna", "ref": "arjuna"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "param", "sa": "परम्", "gram": "nom. sg. n.", "es": "supremo"}, {"iast": "brahma", "sa": "ब्रह्म", "gram": "nom. sg. n.", "es": "brahman", "ref": "brahman"}, {"iast": "dhāma", "sa": "धाम", "gram": "nom. sg. n.", "es": "morada, sede; estado; luz", "analisis": "dhāman, de √dhā (poner, asentar)"}, {"iast": "pavitram", "sa": "पवित्रम्", "gram": "nom. sg. n.", "es": "purificador", "analisis": "de √pū (purificar)"}, {"iast": "paramam", "sa": "परमम्", "gram": "nom. sg. n.", "es": "supremo"}, {"iast": "bhavān", "sa": "भवान्", "gram": "nom. sg. m. pron.", "es": "tú (tratamiento de respeto)", "analisis": "bhavat, «vuestra merced», con el verbo en tercera persona"}, {"iast": "puruṣam", "sa": "पुरुषम्", "gram": "acc. sg. m.", "es": "la Persona", "ref": "purusa"}, {"iast": "śāśvatam", "sa": "शाश्वतम्", "gram": "acc. sg. m.", "es": "eterna", "analisis": "de śaśvat (siempre)"}, {"iast": "divyam", "sa": "दिव्यम्", "gram": "acc. sg. m.", "es": "divina", "analisis": "de div (cielo)"}, {"iast": "ādi-devam", "sa": "आदिदेवम्", "gram": "acc. sg. m. comp.", "es": "el dios primero", "ref": "deva", "analisis": "ādi (comienzo, primero) + deva (dios)"}, {"iast": "ajam", "sa": "अजम्", "gram": "acc. sg. m.", "es": "no nacido", "analisis": "a- (no) + ja (nacido, de √jan)"}, {"iast": "vibhum", "sa": "विभुम्", "gram": "acc. sg. m.", "es": "el que todo lo penetra", "ref": "vibhu", "analisis": "vi-√bhū (extenderse por todas partes)"}], "nota": "<p>Los dos primeros versos de Arjuna forman una sola frase: los acusativos de la segunda línea («a ti, la Persona eterna…») dependen de «así te llaman» del verso siguiente. <em>Bhavān</em>, «vuestra merced», es la forma respetuosa de dirigirse a alguien, con el verbo en tercera persona; el español no tiene un equivalente natural y se traduce «tú». Arjuna aplica a Kṛṣṇa los nombres que hasta ahora se reservaban a lo absoluto: <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a> supremo (<a class=\"vref\" href=\"capitulo-08.html#v3\" data-v=\"8.3\">8.3</a>), la <a class=\"t\" href=\"glosario.html#purusa\" data-t=\"purusa\">Persona</a> suprema y divina (<a class=\"vref\" href=\"capitulo-08.html#v8\" data-v=\"8.8\">8.8</a>–<a class=\"vref\" href=\"capitulo-08.html#v10\" data-v=\"8.10\">8.10</a>), el no nacido (<a class=\"vref\" href=\"capitulo-04.html#v6\" data-v=\"4.6\">4.6</a>, <a class=\"vref\" href=\"capitulo-07.html#v25\" data-v=\"7.25\">7.25</a>). Lo que Kṛṣṇa ha dicho de sí mismo en <a class=\"vref\" href=\"capitulo-10.html#v2\" data-v=\"10.2\">10.2</a>–<a class=\"vref\" href=\"capitulo-10.html#v3\" data-v=\"10.3\">10.3</a>, Arjuna lo devuelve ahora como confesión.</p>", "interp": [{"titulo": "La confesión de Arjuna", "html": "<p>Hasta aquí Arjuna ha preguntado y objetado; en estos versos, por primera vez, confiesa. No añade nada nuevo: reúne los títulos que Kṛṣṇa se ha dado en los capítulos 7 a 10 y se los atribuye con su propia voz. El gesto tiene peso en el relato, porque prepara las dos peticiones que vienen: que Kṛṣṇa enumere sus manifestaciones (<a class=\"vref\" href=\"capitulo-10.html#v16\" data-v=\"10.16\">10.16</a>–<a class=\"vref\" href=\"capitulo-10.html#v18\" data-v=\"10.18\">10.18</a>) y, en el capítulo siguiente, que le muestre su forma universal (<a class=\"vref\" href=\"capitulo-11.html#v3\" data-v=\"11.3\">11.3</a>–<a class=\"vref\" href=\"capitulo-11.html#v4\" data-v=\"11.4\">11.4</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Tú eres el brahman supremo, la luz suprema, el purificador supremo. A ti, la Persona eterna, divina, el dios primero, el no nacido, el que todo lo penetra,", "nota": "<p><em>Dhāman</em> puede ser «morada, sede», «estado» o «luz, esplendor» (véase <a class=\"vref\" href=\"capitulo-08.html#v21\" data-v=\"8.21\">8.21</a>). La traducción principal toma el primero, cerca de <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, que glosa «sostén, refugio» (<em>āśraya</em>), y de Prabhupāda («la morada suprema»); la alternativa, el tercero: «la luz suprema» (<em>paraṃ tejaḥ</em>, <em>paraṃ jyotiḥ</em>) leen <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, y Vedānta Deśika rechaza expresamente el sentido de lugar. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> da las dos glosas, «sostén» o «luz»; Viśvanātha Cakravartī entiende el cuerpo de Kṛṣṇa.</p>"}]}, {"n": 13, "hablante": "arjuna", "sa": ["आहुस्त्वामृषयः सर्वे देवर्षिर्नारदस्तथा ।", "असितो देवलो व्यासः स्वयं चैव ब्रवीषि मे ॥१३॥"], "iast": ["āhus tvām ṛṣayaḥ sarve devarṣir nāradas tathā", "asito devalo vyāsaḥ svayaṃ caiva bravīṣi me"], "rojas": [], "t": "<span class=\"vt-parte\">así te llaman todos los <a class=\"t\" href=\"glosario.html#rsi\" data-t=\"rsi\">videntes</a>, y también el vidente divino <a class=\"t\" href=\"glosario.html#narada\" data-t=\"narada\">Nārada</a>, <a class=\"t\" href=\"glosario.html#devala\" data-t=\"devala\">Asita Devala</a> y <a class=\"t\" href=\"glosario.html#vyasa\" data-t=\"vyasa\">Vyāsa</a>; y tú mismo me lo dices.</span>", "palabras": [{"iast": "āhuḥ", "sa": "आहुः", "gram": "3 pl. pf. act.", "es": "dicen, llaman", "analisis": "√ah (decir), perfecto con valor de presente"}, {"iast": "tvām", "sa": "त्वाम्", "gram": "acc. sg. pron.", "es": "a ti"}, {"iast": "ṛṣayaḥ", "sa": "ऋषयः", "gram": "nom. pl. m.", "es": "los videntes", "ref": "rsi"}, {"iast": "sarve", "sa": "सर्वे", "gram": "nom. pl. m.", "es": "todos"}, {"iast": "devarṣiḥ", "sa": "देवर्षिः", "gram": "nom. sg. m. comp.", "es": "el vidente divino", "ref": "rsi", "analisis": "deva (dios) + ṛṣi (vidente)"}, {"iast": "nāradaḥ", "sa": "नारदः", "gram": "nom. sg. m.", "es": "Nārada", "ref": "narada"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "así, también"}, {"iast": "asitaḥ", "sa": "असितः", "gram": "nom. sg. m.", "es": "Asita", "ref": "devala"}, {"iast": "devalaḥ", "sa": "देवलः", "gram": "nom. sg. m.", "es": "Devala", "ref": "devala"}, {"iast": "vyāsaḥ", "sa": "व्यासः", "gram": "nom. sg. m.", "es": "Vyāsa", "ref": "vyasa"}, {"iast": "svayam", "sa": "स्वयम्", "gram": "ind.", "es": "tú mismo"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "precisamente, también"}, {"iast": "bravīṣi", "sa": "ब्रवीषि", "gram": "2 sg. pres. act.", "es": "dices", "analisis": "√brū (decir)"}, {"iast": "me", "sa": "मे", "gram": "dat. sg. pron.", "es": "a mí"}], "nota": "<p><em>Devarṣi</em>, «vidente divino», es el sabio que vive entre los dioses; Nārada es el ejemplo por excelencia, y Kṛṣṇa lo nombrará como tal entre sus manifestaciones (<a class=\"vref\" href=\"capitulo-10.html#v26\" data-v=\"10.26\">10.26</a>). <em>Asito devalaḥ</em> se entiende de ordinario como un solo nombre, Asita Devala (Devala, hijo de Asita): así parece leerlo <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, que construye los dos nombres con un verbo en singular, y así lo lee <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, que lo identifica con Devala, el hermano mayor de Dhaumya; <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, en cambio, separa a Asita y a Devala (véase la ficha <a class=\"t\" href=\"glosario.html#devala\" data-t=\"devala\">Asita Devala</a>). La lista apela a la autoridad de la tradición: lo que Arjuna cree no se apoya sólo en lo que oye ahora, sino también en lo que dijeron los videntes.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 14, "hablante": "arjuna", "sa": ["सर्वमेतदृतं मन्ये यन्मां वदसि केशव ।", "न हि ते भगवन्व्यक्तिं विदुर्देवा न दानवाः ॥१४॥"], "iast": ["sarvam etad ṛtaṃ manye yan māṃ vadasi keśava", "na hi te bhagavan vyaktiṃ vidur devā na dānavāḥ"], "rojas": [], "t": "<span class=\"vt-parte\">Tengo por verdad todo esto que me dices, oh <a class=\"t\" href=\"glosario.html#kesava\" data-t=\"kesava\">Keśava</a>; porque ni los <a class=\"t\" href=\"glosario.html#deva\" data-t=\"deva\">dioses</a> ni los <a class=\"t\" href=\"glosario.html#daitya\" data-t=\"daitya\">dānavas</a> conocen, oh <a class=\"t\" href=\"glosario.html#bhagavan\" data-t=\"bhagavan\">Señor</a>, tu manifestación.</span>", "palabras": [{"iast": "sarvam", "sa": "सर्वम्", "gram": "acc. sg. n.", "es": "todo"}, {"iast": "etat", "sa": "एतत्", "gram": "acc. sg. n. pron.", "es": "esto"}, {"iast": "ṛtam", "sa": "ऋतम्", "gram": "acc. sg. n.", "es": "verdadero", "analisis": "ṛta (lo recto, el orden verdadero), de √ṛ (ir, ajustarse)"}, {"iast": "manye", "sa": "मन्ये", "gram": "1 sg. pres. med.", "es": "tengo por, considero", "analisis": "√man (pensar)"}, {"iast": "yat", "sa": "यत्", "gram": "acc. sg. n. pron. rel.", "es": "lo que"}, {"iast": "mām", "sa": "माम्", "gram": "acc. sg. pron.", "es": "a mí"}, {"iast": "vadasi", "sa": "वदसि", "gram": "2 sg. pres. act.", "es": "dices", "analisis": "√vad (hablar)"}, {"iast": "keśava", "sa": "केशव", "gram": "voc. sg. m.", "es": "oh Keśava", "ref": "kesava"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no, ni"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "porque, en verdad"}, {"iast": "te", "sa": "ते", "gram": "gen. sg. pron.", "es": "tu"}, {"iast": "bhagavan", "sa": "भगवन्", "gram": "voc. sg. m.", "es": "oh Señor", "ref": "bhagavan"}, {"iast": "vyaktim", "sa": "व्यक्तिम्", "gram": "acc. sg. f.", "es": "la manifestación", "analisis": "vi-√añj (hacer visible, manifestar)"}, {"iast": "viduḥ", "sa": "विदुः", "gram": "3 pl. pf. act.", "es": "conocen", "analisis": "√vid (saber), perfecto con valor de presente"}, {"iast": "devāḥ", "sa": "देवाः", "gram": "nom. pl. m.", "es": "los dioses", "ref": "deva"}, {"iast": "dānavāḥ", "sa": "दानवाः", "gram": "nom. pl. m.", "es": "los dānavas", "ref": "daitya", "analisis": "descendientes de Danu"}], "nota": "<p><em>Vyakti</em>, de vi-√añj, «hacerse visible», es la manifestación de Kṛṣṇa en general, el modo en que se hace presente (así <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lo glosa <em>prabhava</em>, «origen», la palabra de <a class=\"vref\" href=\"capitulo-10.html#v2\" data-v=\"10.2\">10.2</a>, y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, <em>prabhāva</em>, «grandeza»); no es la misma palabra que <em>vibhūti</em>, «manifestación divina», que Arjuna pedirá en <a class=\"vref\" href=\"capitulo-10.html#v16\" data-v=\"10.16\">10.16</a> y que da nombre al capítulo. El verso repite, desde el lado de Arjuna, lo que Kṛṣṇa dijo en <a class=\"vref\" href=\"capitulo-10.html#v2\" data-v=\"10.2\">10.2</a>: ni las multitudes de dioses ni los grandes videntes conocen su origen. Los <a class=\"t\" href=\"glosario.html#daitya\" data-t=\"daitya\">dānavas</a>, hijos de Danu, son, con los daityas, los enemigos tradicionales de los dioses: la pareja «dioses y dānavas» es una manera de decir «nadie, ni en el cielo ni fuera de él».</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 15, "hablante": "arjuna", "sa": ["स्वयमेवात्मनात्मानं वेत्थ त्वं पुरुषोत्तम ।", "भूतभावन भूतेश देवदेव जगत्पते ॥१५॥"], "iast": ["svayam evātmanātmānaṃ vettha tvaṃ puruṣottama", "bhūta-bhāvana bhūteśa deva-deva jagat-pate"], "rojas": [], "t": "<span class=\"vt-parte\">Sólo tú te conoces a ti mismo por ti mismo, oh <a class=\"t\" href=\"glosario.html#purusottama\" data-t=\"purusottama\">Puruṣottama</a>, origen de los seres, señor de los seres, dios de los dioses, señor del mundo.</span>", "palabras": [{"iast": "svayam", "sa": "स्वयम्", "gram": "ind.", "es": "tú mismo"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "sólo, precisamente"}, {"iast": "ātmanā", "sa": "आत्मना", "gram": "instr. sg. m.", "es": "por ti mismo", "ref": "atman"}, {"iast": "ātmānam", "sa": "आत्मानम्", "gram": "acc. sg. m.", "es": "a ti mismo", "ref": "atman"}, {"iast": "vettha", "sa": "वेत्थ", "gram": "2 sg. pf. act.", "es": "conoces", "analisis": "√vid (saber), perfecto con valor de presente"}, {"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "puruṣottama", "sa": "पुरुषोत्तम", "gram": "voc. sg. m. comp.", "es": "oh Persona suprema", "ref": "purusottama", "analisis": "puruṣa (persona) + uttama (el más alto)"}, {"iast": "bhūta-bhāvana", "sa": "भूतभावन", "gram": "voc. sg. m. comp.", "es": "oh origen de los seres", "analisis": "bhūta (ser) + bhāvana (el que hace ser, de √bhū causativo)"}, {"iast": "bhūteśa", "sa": "भूतेश", "gram": "voc. sg. m. comp.", "es": "oh señor de los seres", "analisis": "bhūta (ser) + īśa (señor)"}, {"iast": "deva-deva", "sa": "देवदेव", "gram": "voc. sg. m. comp.", "es": "oh dios de los dioses", "ref": "deva", "analisis": "deva (dios) + deva (dios)"}, {"iast": "jagat-pate", "sa": "जगत्पते", "gram": "voc. sg. m. comp.", "es": "oh señor del mundo", "analisis": "jagat (el mundo, lo que se mueve) + pati (señor)"}], "nota": "<p><em>Svayam evātmanātmānam</em>: «tú mismo, por ti mismo, a ti mismo»; la triple repetición subraya que nadie más tiene acceso a ese conocimiento, como acaba de decir el verso anterior. Siguen cinco vocativos, que van de lo más íntimo a lo más amplio: <a class=\"t\" href=\"glosario.html#purusottama\" data-t=\"purusottama\">Puruṣottama</a>, «la Persona suprema», que el capítulo 15 explicará (<a class=\"vref\" href=\"capitulo-15.html#v18\" data-v=\"15.18\">15.18</a>); <em>bhūta-bhāvana</em>, el que hace existir a los seres (la misma expresión de <a class=\"vref\" href=\"capitulo-09.html#v5\" data-v=\"9.5\">9.5</a>, «mi propio ser es el que hace existir a los seres»); <em>bhūteśa</em>, su señor; <em>deva-deva</em>, el dios de los dioses; y <em>jagat-pati</em>, el señor del mundo. La acumulación es un recurso del himno: Arjuna habla ya como quien alaba.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 16, "hablante": "arjuna", "sa": ["वक्तुमर्हस्यशेषेण दिव्या ह्यात्मविभूतयः ।", "याभिर्विभूतिभिर्लोकानिमांस्त्वं व्याप्य तिष्ठसि ॥१६॥"], "iast": ["vaktum arhasy aśeṣeṇa divyā hy ātma-vibhūtayaḥ", "yābhir vibhūtibhir lokān imāṃs tvaṃ vyāpya tiṣṭhasi"], "rojas": [], "t": "<span class=\"vt-parte\">Dígnate decirme por entero tus <a class=\"t\" href=\"glosario.html#vibhuti\" data-t=\"vibhuti\">manifestaciones</a> divinas, esas manifestaciones con las que permaneces en estos mundos, penetrándolos.</span>", "palabras": [{"iast": "vaktum", "sa": "वक्तुम्", "gram": "inf.", "es": "decir", "analisis": "√vac (hablar)"}, {"iast": "arhasi", "sa": "अर्हसि", "gram": "2 sg. pres. act.", "es": "debes, dígnate", "analisis": "√arh (merecer, ser digno); con infinitivo, ruego cortés"}, {"iast": "aśeṣeṇa", "sa": "अशेषेण", "gram": "instr. sg. m. (adv.)", "es": "sin dejar nada, por entero", "analisis": "a- (sin) + śeṣa (resto)"}, {"iast": "divyāḥ", "sa": "दिव्याः", "gram": "nom. pl. f.", "es": "divinas"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues, en verdad"}, {"iast": "ātma-vibhūtayaḥ", "sa": "आत्मविभूतयः", "gram": "nom. pl. f. comp.", "es": "tus propias manifestaciones", "ref": "vibhuti", "analisis": "ātman (uno mismo) + vibhūti (manifestación, poder que se despliega; de vi-√bhū)"}, {"iast": "yābhiḥ", "sa": "याभिः", "gram": "instr. pl. f. pron. rel.", "es": "con las cuales"}, {"iast": "vibhūtibhiḥ", "sa": "विभूतिभिः", "gram": "instr. pl. f.", "es": "manifestaciones", "ref": "vibhuti"}, {"iast": "lokān", "sa": "लोकान्", "gram": "acc. pl. m.", "es": "los mundos"}, {"iast": "imān", "sa": "इमान्", "gram": "acc. pl. m. pron.", "es": "estos"}, {"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "vyāpya", "sa": "व्याप्य", "gram": "ger.", "es": "penetrando", "analisis": "vi-√āp (alcanzar por todas partes, llenar)"}, {"iast": "tiṣṭhasi", "sa": "तिष्ठसि", "gram": "2 sg. pres. act.", "es": "permaneces, estás", "analisis": "√sthā (estar de pie, permanecer)"}], "nota": "<p><em>Vaktum arhasi</em>, literalmente «mereces decir», es la misma construcción, infinitivo más <em>arhasi</em>, con que Kṛṣṇa le decía a Arjuna «no debes afligirte» (<a class=\"vref\" href=\"capitulo-02.html#v25\" data-v=\"2.25\">2.25</a>) o «debes actuar» (<a class=\"vref\" href=\"capitulo-03.html#v20\" data-v=\"3.20\">3.20</a>); en boca de Arjuna es un ruego cortés, como ya en <a class=\"vref\" href=\"capitulo-06.html#v39\" data-v=\"6.39\">6.39</a> («te ruego que cortes») y de nuevo en <a class=\"vref\" href=\"capitulo-11.html#v44\" data-v=\"11.44\">11.44</a>, y se traduce «dígnate». La palabra clave del capítulo, <a class=\"t\" href=\"glosario.html#vibhuti\" data-t=\"vibhuti\"><em>vibhūti</em></a>, aparece aquí dos veces: de vi-√bhū, «extenderse, llegar a ser de muchas maneras», es la manifestación del poder divino en lo que existe. Kṛṣṇa ya la había nombrado en <a class=\"vref\" href=\"capitulo-10.html#v7\" data-v=\"10.7\">10.7</a>; Arjuna la pide ahora con detalle.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 17, "hablante": "arjuna", "sa": ["कथं विद्यामहं योगिंस्त्वां सदा परिचिन्तयन् ।", "केषु केषु च भावेषु चिन्त्योऽसि भगवन्मया ॥१७॥"], "iast": ["kathaṃ vidyām ahaṃ yogiṃs tvāṃ sadā paricintayan", "keṣu keṣu ca bhāveṣu cintyo 'si bhagavan mayā"], "rojas": [], "t": "<span class=\"vt-parte\">¿Cómo he de conocerte, oh <a class=\"t\" href=\"glosario.html#yogin\" data-t=\"yogin\">yogui</a>, pensando siempre en ti? ¿Y en qué estados, en cuáles, he de pensarte, oh <a class=\"t\" href=\"glosario.html#bhagavan\" data-t=\"bhagavan\">Señor</a>?</span>", "palabras": [{"iast": "katham", "sa": "कथम्", "gram": "ind.", "es": "cómo"}, {"iast": "vidyām", "sa": "विद्याम्", "gram": "1 sg. opt. act.", "es": "he de conocer, podré conocer", "analisis": "√vid (saber)"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "yogin", "sa": "योगिन्", "gram": "voc. sg. m.", "es": "oh yogui", "ref": "yogin", "analisis": "yogin (el que posee el yoga)"}, {"iast": "tvām", "sa": "त्वाम्", "gram": "acc. sg. pron.", "es": "a ti"}, {"iast": "sadā", "sa": "सदा", "gram": "ind.", "es": "siempre"}, {"iast": "paricintayan", "sa": "परिचिन्तयन्", "gram": "pres. part. act. nom. sg. m.", "es": "pensando, meditando", "analisis": "pari-√cint (pensar en algo por todos lados)"}, {"iast": "keṣu", "sa": "केषु", "gram": "loc. pl. m. interr.", "es": "en cuáles"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "bhāveṣu", "sa": "भावेषु", "gram": "loc. pl. m.", "es": "en los estados, en las cosas", "analisis": "bhāva (estado, modo de ser, cosa existente; de √bhū)"}, {"iast": "cintyaḥ", "sa": "चिन्त्यः", "gram": "nom. sg. m. gerundivo", "es": "has de ser pensado", "analisis": "√cint (pensar)"}, {"iast": "asi", "sa": "असि", "gram": "2 sg. pres.", "es": "eres", "analisis": "√as (ser)"}, {"iast": "bhagavan", "sa": "भगवन्", "gram": "voc. sg. m.", "es": "oh Señor", "ref": "bhagavan"}, {"iast": "mayā", "sa": "मया", "gram": "instr. sg. pron.", "es": "por mí"}], "nota": "<p><em>Keṣu keṣu</em>, «en cuáles y en cuáles», con la repetición distributiva del sánscrito: Arjuna pide una lista, cosa por cosa. <em>Bhāva</em> es aquí el modo de ser, la cosa existente en que puede pensarse a Kṛṣṇa; la misma palabra designaba en <a class=\"vref\" href=\"capitulo-07.html#v12\" data-v=\"7.12\">7.12</a> los «estados» que nacen de las guṇas. La pregunta es práctica: no qué es Kṛṣṇa, sino dónde fijar el pensamiento para meditar en él, lo que enlaza con la meditación constante que pedían <a class=\"vref\" href=\"capitulo-08.html#v7\" data-v=\"8.7\">8.7</a> y <a class=\"vref\" href=\"capitulo-09.html#v34\" data-v=\"9.34\">9.34</a>.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "¿Cómo he de conocerte, oh señor del yoga, pensando siempre en ti? ¿Y en qué estados, en cuáles, he de pensarte, oh Señor?", "nota": "<p><em>Yogin</em>, dicho de Kṛṣṇa, no es el que practica el yoga, sino el que lo posee (así <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>: «el que tiene un poder sin igual»; <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, en cambio, aplica <em>yogī</em> al propio Arjuna, entregado al yoga de la devoción): el dueño de ese poder que el capítulo 9 llamó «mi yoga soberano» (<a class=\"vref\" href=\"capitulo-09.html#v5\" data-v=\"9.5\">9.5</a>) y del que Arjuna pide, en el verso siguiente, que le hable por extenso. La traducción principal conserva la palabra; la alternativa hace explícito ese sentido, el mismo de <em>yogeśvara</em>, «señor del yoga», con que Arjuna y Sañjaya lo nombrarán más adelante (<a class=\"vref\" href=\"capitulo-11.html#v4\" data-v=\"11.4\">11.4</a>, <a class=\"vref\" href=\"capitulo-18.html#v75\" data-v=\"18.75\">18.75</a>).</p>"}]}, {"n": 18, "hablante": "arjuna", "sa": ["विस्तरेणात्मनो योगं विभूतिं च जनार्दन ।", "भूयः कथय तृप्तिर्हि शृण्वतो नास्ति मेऽमृतम् ॥१८॥"], "iast": ["vistareṇātmano yogaṃ vibhūtiṃ ca janārdana", "bhūyaḥ kathaya tṛptir hi śṛṇvato nāsti me 'mṛtam"], "rojas": [], "t": "<span class=\"vt-parte\">Explícame otra vez, con detalle, tu <a class=\"t\" href=\"glosario.html#yoga-maya\" data-t=\"yoga-maya\">yoga</a> y tu <a class=\"t\" href=\"glosario.html#vibhuti\" data-t=\"vibhuti\">manifestación</a>, oh <a class=\"t\" href=\"glosario.html#janardana\" data-t=\"janardana\">Janārdana</a>; porque, al escuchar este néctar, no me sacio.</span>", "palabras": [{"iast": "vistareṇa", "sa": "विस्तरेण", "gram": "instr. sg. m. (adv.)", "es": "con detalle, por extenso", "analisis": "vi-√stṛ (extender)"}, {"iast": "ātmanaḥ", "sa": "आत्मनः", "gram": "gen. sg. m.", "es": "tuyo propio", "ref": "atman"}, {"iast": "yogam", "sa": "योगम्", "gram": "acc. sg. m.", "es": "el yoga, el poder", "ref": "yoga-maya"}, {"iast": "vibhūtim", "sa": "विभूतिम्", "gram": "acc. sg. f.", "es": "la manifestación", "ref": "vibhuti"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "janārdana", "sa": "जनार्दन", "gram": "voc. sg. m.", "es": "oh Janārdana", "ref": "janardana"}, {"iast": "bhūyaḥ", "sa": "भूयः", "gram": "ind.", "es": "de nuevo, otra vez"}, {"iast": "kathaya", "sa": "कथय", "gram": "2 sg. impv. act.", "es": "cuenta, explica", "analisis": "√kath (contar, narrar)"}, {"iast": "tṛptiḥ", "sa": "तृप्तिः", "gram": "nom. sg. f.", "es": "saciedad", "analisis": "√tṛp (saciarse)"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "porque"}, {"iast": "śṛṇvataḥ", "sa": "शृण्वतः", "gram": "pres. part. act. gen. sg. m.", "es": "del que escucha", "analisis": "√śru (oír)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "asti", "sa": "अस्ति", "gram": "3 sg. pres.", "es": "hay", "analisis": "√as (ser)"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "para mí"}, {"iast": "amṛtam", "sa": "अमृतम्", "gram": "acc. sg. n.", "es": "el néctar", "analisis": "a- (no) + mṛta (muerto): «lo inmortal», el néctar de la inmortalidad"}], "nota": "<p><em>Yoga</em> es aquí el poder de Kṛṣṇa, su «yoga soberano» (<a class=\"vref\" href=\"capitulo-09.html#v5\" data-v=\"9.5\">9.5</a>): <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo glosan como el poder del yoga, la omnisciencia y la omnipotencia, y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, como su condición de creador; por eso enlaza con la ficha <a class=\"t\" href=\"glosario.html#yoga-maya\" data-t=\"yoga-maya\">yoga-māyā</a>, que explica ese sentido. <em>Bhūyaḥ</em>, «de nuevo»: Kṛṣṇa ya ha hablado de sus manifestaciones en <a class=\"vref\" href=\"capitulo-07.html#v8\" data-v=\"7.8\">7.8</a>–<a class=\"vref\" href=\"capitulo-07.html#v11\" data-v=\"7.11\">7.11</a> y <a class=\"vref\" href=\"capitulo-09.html#v16\" data-v=\"9.16\">9.16</a>–<a class=\"vref\" href=\"capitulo-09.html#v19\" data-v=\"9.19\">9.19</a>, y Arjuna pide que lo repita por extenso. <em>Amṛta</em>, «lo que no muere», es el néctar de la inmortalidad que bebían los dioses: las palabras de Kṛṣṇa son para Arjuna una bebida de la que no se cansa, como para los devotos de <a class=\"vref\" href=\"capitulo-10.html#v9\" data-v=\"10.9\">10.9</a>, que se deleitan hablando de él.</p>", "interp": [{"titulo": "La petición que abre la lista", "html": "<p>Con estos tres versos (<a class=\"vref\" href=\"capitulo-10.html#v16\" data-v=\"10.16\">10.16</a>–<a class=\"vref\" href=\"capitulo-10.html#v18\" data-v=\"10.18\">10.18</a>) Arjuna pone en marcha el resto del capítulo: lo que sigue, hasta <a class=\"vref\" href=\"capitulo-10.html#v42\" data-v=\"10.42\">10.42</a>, es la respuesta a su ruego, la enumeración de las manifestaciones de Kṛṣṇa. La petición tiene dos caras. Una es práctica: saber en qué cosas pensar para meditar en él (<a class=\"vref\" href=\"capitulo-10.html#v17\" data-v=\"10.17\">10.17</a>). La otra es el deseo de oír más, que no se sacia (<a class=\"vref\" href=\"capitulo-10.html#v18\" data-v=\"10.18\">10.18</a>). Ese mismo deseo, llevado más lejos, le hará pedir en el capítulo siguiente no ya oír, sino ver (<a class=\"vref\" href=\"capitulo-11.html#v3\" data-v=\"11.3\">11.3</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 19, "hablante": "krsna", "sa": ["श्रीभगवानुवाच ।", "हन्त ते कथयिष्यामि दिव्या ह्यात्मविभूतयः ।", "प्राधान्यतः कुरुश्रेष्ठ नास्त्यन्तो विस्तरस्य मे ॥१९॥"], "iast": ["śrī-bhagavān uvāca", "hanta te kathayiṣyāmi divyā hy ātma-vibhūtayaḥ", "prādhānyataḥ kuru-śreṣṭha nāsty anto vistarasya me"], "rojas": [1, 2], "t": "<span class=\"vt-parte voz-krsna\">Muy bien: te hablaré de mis <a class=\"t\" href=\"glosario.html#vibhuti\" data-t=\"vibhuti\">manifestaciones</a> divinas, oh Kuruśreṣṭha, de las principales; porque mi extensión no tiene fin.</span>", "palabras": [{"iast": "śrī-bhagavān", "sa": "श्रीभगवान्", "gram": "nom. sg. m.", "es": "el Señor glorioso", "ref": "bhagavan"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. perf.", "es": "dijo"}, {"iast": "hanta", "sa": "हन्त", "gram": "interj.", "es": "¡bien!, ¡ea!", "analisis": "partícula que anuncia que se va a hacer lo pedido"}, {"iast": "te", "sa": "ते", "gram": "dat. sg.", "es": "a ti"}, {"iast": "kathayiṣyāmi", "sa": "कथयिष्यामि", "gram": "1 sg. fut.", "es": "contaré, expondré", "analisis": "√kath (contar, narrar)"}, {"iast": "divyāḥ", "sa": "दिव्याः", "gram": "ac. pl. f.", "es": "divinas"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues, en efecto"}, {"iast": "ātma-vibhūtayaḥ", "sa": "आत्मविभूतयः", "gram": "ac. pl. f. comp.", "es": "mis propias manifestaciones", "ref": "vibhuti", "analisis": "ātman (sí mismo, propio) + vibhūti (manifestación, poder que se despliega)"}, {"iast": "prādhānyataḥ", "sa": "प्राधान्यतः", "gram": "adv.", "es": "según su preeminencia, las principales", "analisis": "prādhānya (preeminencia) + -tas (según)"}, {"iast": "kuru-śreṣṭha", "sa": "कुरुश्रेष्ठ", "gram": "voc. sg. m. comp.", "es": "oh el mejor de los Kurus", "analisis": "kuru (los Kurus) + śreṣṭha (el mejor)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "asti", "sa": "अस्ति", "gram": "3 sg. pres.", "es": "hay"}, {"iast": "antaḥ", "sa": "अन्तः", "gram": "nom. sg. m.", "es": "fin"}, {"iast": "vistarasya", "sa": "विस्तरस्य", "gram": "gen. sg. m.", "es": "de la extensión", "analisis": "vi-√stṛ (extender)"}, {"iast": "me", "sa": "मे", "gram": "gen. sg.", "es": "mía"}], "nota": "<p>Kṛṣṇa responde a la petición de <a class=\"t\" href=\"glosario.html#arjuna\" data-t=\"arjuna\">Arjuna</a> (<a class=\"vref\" href=\"capitulo-10.html#v16\" data-v=\"10.16\">10.16</a>–<a class=\"vref\" href=\"capitulo-10.html#v18\" data-v=\"10.18\">10.18</a>). <em>Hanta</em> es la partícula con que se acepta lo pedido: «¡bien!, ¡ea!». <em>Prādhānyataḥ</em>, «según la preeminencia»: no las dirá todas, sino las más destacadas, porque una enumeración completa es imposible; lo repetirá al cerrar la lista (<a class=\"vref\" href=\"capitulo-10.html#v40\" data-v=\"10.40\">10.40</a>). <em>Kuru-śreṣṭha</em>, «el mejor de los Kurus», es un vocativo de cortesía dirigido a Arjuna, de la misma familia que <a class=\"t\" href=\"glosario.html#kurusattama\" data-t=\"kurusattama\">Kurusattama</a> (<a class=\"vref\" href=\"capitulo-04.html#v31\" data-v=\"4.31\">4.31</a>).</p>", "interp": [{"titulo": "Una lista que no puede terminar", "html": "<p>El verso abre la gran enumeración del capítulo y, a la vez, la relativiza: lo que sigue no es un inventario, sino una muestra. Kṛṣṇa lo dirá de nuevo al final: no hay término para sus manifestaciones, y lo dicho es sólo un ejemplo de su extensión (<a class=\"vref\" href=\"capitulo-10.html#v40\" data-v=\"10.40\">10.40</a>); todo lo que tiene gloria, belleza o fuerza nace de una parte de su esplendor (<a class=\"vref\" href=\"capitulo-10.html#v41\" data-v=\"10.41\">10.41</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-si-mismo-en-el-corazon-de-los-seres"}, {"n": 20, "hablante": "krsna", "sa": ["अहमात्मा गुडाकेश सर्वभूताशयस्थितः ।", "अहमादिश्च मध्यं च भूतानामन्त एव च ॥२०॥"], "iast": ["aham ātmā guḍākeśa sarva-bhūtāśaya-sthitaḥ", "aham ādiś ca madhyaṃ ca bhūtānām anta eva ca"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Yo soy el <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">sí-mismo</a>, oh <a class=\"t\" href=\"glosario.html#gudakesa\" data-t=\"gudakesa\">Guḍākeśa</a>, que mora en el corazón de todos los seres; yo soy el principio, el medio y también el fin de los seres.</span>", "palabras": [{"iast": "aham", "sa": "अहम्", "gram": "nom. sg.", "es": "yo"}, {"iast": "ātmā", "sa": "आत्मा", "gram": "nom. sg. m.", "es": "el sí-mismo", "ref": "atman"}, {"iast": "guḍākeśa", "sa": "गुडाकेश", "gram": "voc. sg. m.", "es": "oh Guḍākeśa (Arjuna)", "ref": "gudakesa"}, {"iast": "sarva-bhūta-āśaya-sthitaḥ", "sa": "सर्वभूताशयस्थितः", "gram": "nom. sg. m. comp.", "es": "que mora en el corazón de todos los seres", "analisis": "sarva (todos) + bhūta (ser) + āśaya (morada, asiento; el corazón) + sthita (que está)"}, {"iast": "ādiḥ", "sa": "आदिः", "gram": "nom. sg. m.", "es": "el principio"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "madhyam", "sa": "मध्यम्", "gram": "nom. sg. n.", "es": "el medio"}, {"iast": "bhūtānām", "sa": "भूतानाम्", "gram": "gen. pl. n.", "es": "de los seres"}, {"iast": "antaḥ", "sa": "अन्तः", "gram": "nom. sg. m.", "es": "el fin"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "también, precisamente"}], "nota": "<p>Antes de enumerar nada, Kṛṣṇa dice qué es lo que se va a ver en cada una de sus manifestaciones: él mismo, como el sí-mismo de todo ser. La segunda mitad retoma <a class=\"vref\" href=\"capitulo-07.html#v6\" data-v=\"7.6\">7.6</a> y <a class=\"vref\" href=\"capitulo-09.html#v18\" data-v=\"9.18\">9.18</a>: es el origen, la permanencia y la disolución de los seres. <em>Guḍākeśa</em>, epíteto de Arjuna, se entiende como «el que ha vencido el sueño» o «el de cabello espeso», las dos glosas de <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> (véase la ficha).</p>", "interp": [{"titulo": "La clave de toda la lista", "html": "<p>Este verso gobierna todo lo que sigue. Lo que Kṛṣṇa va a nombrar en cada clase —Viṣṇu entre los Ādityas, el océano entre las aguas, el Himālaya entre lo inmóvil— no es una colección de cosas admirables, sino otros tantos lugares donde se deja ver lo que este verso dice sin imágenes: que él es el sí-mismo en el corazón de cada ser y el principio, el medio y el fin de todos. La lista termina con la misma idea: él es la semilla de todos los seres, y nada puede existir sin él (<a class=\"vref\" href=\"capitulo-10.html#v39\" data-v=\"10.39\">10.39</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "Meditar en él como el sí-mismo", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> leen el verso como la primera y más alta forma de meditar en el Señor: como el sí-mismo interior de cada uno. Las manifestaciones que siguen serían apoyos para la meditación de quien todavía no es capaz de esa forma, la más alta.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "El cuerpo y su sí-mismo", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> ve en este verso la clave gramatical de toda la lista: los seres son el cuerpo de Kṛṣṇa, y él mora en ellos como su sí-mismo, que los sostiene, los gobierna y es su dueño. Por eso puede decir «soy Viṣṇu», «soy el Sāma»: como las palabras «dios» u «hombre», que nombran un cuerpo, designan en último término al que lo habita, cada nombre de la lista lo designa a él. La lista se cierra con la misma idea (<a class=\"vref\" href=\"capitulo-10.html#v39\" data-v=\"10.39\">10.39</a>).</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Yo soy el sí-mismo, oh Guḍākeśa, que reside en todos los seres como en su morada; yo soy el principio, el medio y también el fin de los seres.", "nota": "<p><em>Āśaya</em> es «lugar de reposo, morada, asiento», y de ahí también «el corazón» o «el interior», donde residen el pensamiento y las inclinaciones. La traducción principal toma el sentido concreto, el corazón, que es como lo glosan <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> (<a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>: «los órganos internos», la mente); la alternativa conserva el sentido más amplio de morada: Kṛṣṇa está en todos los seres como quien habita en su casa.</p>"}], "ens": "el-si-mismo-en-el-corazon-de-los-seres"}, {"n": 21, "hablante": "krsna", "sa": ["आदित्यानामहं विष्णुर्ज्योतिषां रविरंशुमान् ।", "मरीचिर्मरुतामस्मि नक्षत्राणामहं शशी ॥२१॥"], "iast": ["ādityānām ahaṃ viṣṇur jyotiṣāṃ ravir aṃśumān", "marīcir marutām asmi nakṣatrāṇām ahaṃ śaśī"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Entre los <a class=\"t\" href=\"glosario.html#aditya\" data-t=\"aditya\">Ādityas</a> soy <a class=\"t\" href=\"glosario.html#visnu\" data-t=\"visnu\">Viṣṇu</a>; entre las luces, el sol radiante; entre los <a class=\"t\" href=\"glosario.html#marut\" data-t=\"marut\">Maruts</a> soy <a class=\"t\" href=\"glosario.html#marici\" data-t=\"marici\">Marīci</a>; entre los astros soy la luna.</span>", "palabras": [{"iast": "ādityānām", "sa": "आदित्यानाम्", "gram": "gen. pl. m.", "es": "entre los Ādityas", "ref": "aditya", "analisis": "āditya: «hijo de Aditi»"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg.", "es": "yo"}, {"iast": "viṣṇuḥ", "sa": "विष्णुः", "gram": "nom. sg. m.", "es": "Viṣṇu", "ref": "visnu"}, {"iast": "jyotiṣām", "sa": "ज्योतिषाम्", "gram": "gen. pl. n.", "es": "entre las luces, entre los cuerpos luminosos"}, {"iast": "raviḥ", "sa": "रविः", "gram": "nom. sg. m.", "es": "el sol"}, {"iast": "aṃśumān", "sa": "अंशुमान्", "gram": "nom. sg. m.", "es": "radiante", "analisis": "aṃśu (rayo) + -mat (que tiene)"}, {"iast": "marīciḥ", "sa": "मरीचिः", "gram": "nom. sg. m.", "es": "Marīci", "ref": "marici"}, {"iast": "marutām", "sa": "मरुताम्", "gram": "gen. pl. m.", "es": "entre los Maruts", "ref": "marut"}, {"iast": "asmi", "sa": "अस्मि", "gram": "1 sg. pres.", "es": "soy"}, {"iast": "nakṣatrāṇām", "sa": "नक्षत्राणाम्", "gram": "gen. pl. n.", "es": "entre los astros, entre las constelaciones lunares"}, {"iast": "śaśī", "sa": "शशी", "gram": "nom. sg. m.", "es": "la luna", "analisis": "śaśin: «el que tiene la liebre», por la figura que se ve en ella"}], "nota": "<p>Empieza la lista propiamente dicha, con su fórmula fija: «entre los X soy Y», es decir, de cada clase, lo más alto. Los <em>Āditya</em>, hijos de la diosa Aditi, son un grupo de dioses que los textos posteriores fijan en doce; Viṣṇu es uno de ellos (véase la ficha). <em>Jyotis</em> es todo lo que da luz, y entre las luces la mayor es el sol. Los <em>Marut</em> son los dioses de la tormenta, compañeros de Indra. <em>Nakṣatra</em> son los astros y, en particular, las veintisiete (o veintiocho) constelaciones que la luna recorre en su ciclo; <em>śaśin</em>, «el que lleva la liebre», es la luna, por la figura que el ojo indio ve en sus manchas.</p>", "interp": [{"titulo": "Viṣṇu entre los Ādityas", "html": "<p>En el Veda, Viṣṇu es un dios secundario, conocido sobre todo por sus tres pasos con que mide el universo; más tarde se le cuenta entre los doce Ādityas, y los Purāṇas lo identifican con Vāmana, el enano, hijo de Aditi, que recupera el mundo con esos tres pasos. Así lo glosa aquí <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> («Viṣṇu, es decir, Vāmana»), y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo da como segunda opción; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> dicen sólo «el Āditya llamado Viṣṇu». Que el primer nombre de la lista sea el de Viṣṇu no es casual: Kṛṣṇa, que en la tradición es un descenso de Viṣṇu, empieza nombrándolo a él.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "lo-mas-alto-entre-los-dioses-y-los-sabios"}, {"n": 22, "hablante": "krsna", "sa": ["वेदानां सामवेदोऽस्मि देवानामस्मि वासवः ।", "इन्द्रियाणां मनश्चास्मि भूतानामस्मि चेतना ॥२२॥"], "iast": ["vedānāṃ sāma-vedo 'smi devānām asmi vāsavaḥ", "indriyāṇāṃ manaś cāsmi bhūtānām asmi cetanā"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Entre los Vedas soy el <a class=\"t\" href=\"glosario.html#sama-veda\" data-t=\"sama-veda\">Sāma</a>; entre los <a class=\"t\" href=\"glosario.html#deva\" data-t=\"deva\">dioses</a> soy <a class=\"t\" href=\"glosario.html#indra\" data-t=\"indra\">Vāsava</a>; entre los <a class=\"t\" href=\"glosario.html#indriya\" data-t=\"indriya\">sentidos</a> soy la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a>, y en los seres soy la conciencia.</span>", "palabras": [{"iast": "vedānām", "sa": "वेदानाम्", "gram": "gen. pl. m.", "es": "entre los Vedas", "ref": "veda"}, {"iast": "sāma-vedaḥ", "sa": "सामवेदः", "gram": "nom. sg. m. comp.", "es": "el Sāma-veda", "ref": "sama-veda", "analisis": "sāman (canto) + veda"}, {"iast": "asmi", "sa": "अस्मि", "gram": "1 sg. pres.", "es": "soy"}, {"iast": "devānām", "sa": "देवानाम्", "gram": "gen. pl. m.", "es": "entre los dioses", "ref": "deva"}, {"iast": "vāsavaḥ", "sa": "वासवः", "gram": "nom. sg. m.", "es": "Vāsava (Indra)", "ref": "indra", "analisis": "vāsava: «señor de los Vasus»"}, {"iast": "indriyāṇām", "sa": "इन्द्रियाणाम्", "gram": "gen. pl. n.", "es": "entre los sentidos", "ref": "indriya"}, {"iast": "manaḥ", "sa": "मनः", "gram": "nom. sg. n.", "es": "la mente", "ref": "manas"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "bhūtānām", "sa": "भूतानाम्", "gram": "gen. pl. n.", "es": "en los seres, entre los seres"}, {"iast": "cetanā", "sa": "चेतना", "gram": "nom. sg. f.", "es": "la conciencia, la facultad de conocer", "analisis": "√cit (percibir, ser consciente)"}], "nota": "<p>El <em>Sāma-veda</em> es el Veda de los cantos: pone en música versos que en su mayoría proceden del Ṛg-veda. <em>Vāsava</em>, «el de los Vasus», es un nombre de <a class=\"t\" href=\"glosario.html#indra\" data-t=\"indra\">Indra</a>, rey de los dioses. La mente es «la primera» de los sentidos porque sin ella ninguno percibe: está entre ellos y por encima de ellos, como dirá <a class=\"vref\" href=\"capitulo-15.html#v7\" data-v=\"15.7\">15.7</a> (la mente como sexto sentido).</p>", "interp": [{"titulo": "El canto, esencia del Veda", "html": "<p>Que entre los Vedas Kṛṣṇa sea el Sāma tiene un antecedente en las Upaniṣads: la <em>Chāndogya</em>, que pertenece a la tradición del Sāma-veda, dice que la esencia de la palabra es el verso del Ṛg, la esencia del verso es el canto (<em>sāman</em>) y la esencia del canto, la sílaba que se entona (1.1.2). El canto es el verso hecho música, lo más refinado del Veda.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Entre los Vedas soy el Sāma; entre los dioses soy Vāsava; entre los sentidos soy la mente, y en los seres soy la facultad de conocer.", "nota": "<p><em>Cetanā</em> puede ser la conciencia misma o la facultad por la que el ser vivo percibe y conoce. La traducción principal deja la palabra amplia, como <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, para quien es la conciencia misma de los seres conscientes; la alternativa la entiende, con <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, como una función del entendimiento (<em>buddhi-vṛtti</em>) siempre manifiesta en el conjunto del cuerpo y los sentidos; <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> la glosa igual, como la función del entendimiento que hace manifiesta la conciencia, y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, como la facultad de conocer (<em>jñāna-śakti</em>).</p>"}], "ens": "lo-mas-alto-entre-los-dioses-y-los-sabios"}, {"n": 23, "hablante": "krsna", "sa": ["रुद्राणां शङ्करश्चास्मि वित्तेशो यक्षरक्षसाम् ।", "वसूनां पावकश्चास्मि मेरुः शिखरिणामहम् ॥२३॥"], "iast": ["rudrāṇāṃ śaṅkaraś cāsmi vitteśo yakṣa-rakṣasām", "vasūnāṃ pāvakaś cāsmi meruḥ śikhariṇām aham"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Entre los <a class=\"t\" href=\"glosario.html#rudra\" data-t=\"rudra\">Rudras</a> soy <a class=\"t\" href=\"glosario.html#rudra\" data-t=\"rudra\">Śaṅkara</a>; entre los yakṣas y los <a class=\"t\" href=\"glosario.html#raksasa\" data-t=\"raksasa\">rākṣasas</a>, el <a class=\"t\" href=\"glosario.html#kubera\" data-t=\"kubera\">señor de las riquezas</a>; entre los <a class=\"t\" href=\"glosario.html#vasu\" data-t=\"vasu\">Vasus</a> soy <a class=\"t\" href=\"glosario.html#agni\" data-t=\"agni\">Pāvaka</a>, y entre los montes soy el <a class=\"t\" href=\"glosario.html#meru\" data-t=\"meru\">Meru</a>.</span>", "palabras": [{"iast": "rudrāṇām", "sa": "रुद्राणाम्", "gram": "gen. pl. m.", "es": "entre los Rudras", "ref": "rudra"}, {"iast": "śaṅkaraḥ", "sa": "शङ्करः", "gram": "nom. sg. m.", "es": "Śaṅkara (Śiva)", "ref": "rudra", "analisis": "śam (bien, dicha) + -kara (que hace): «el que trae el bien»"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "asmi", "sa": "अस्मि", "gram": "1 sg. pres.", "es": "soy"}, {"iast": "vitta-īśaḥ", "sa": "वित्तेशः", "gram": "nom. sg. m. comp.", "es": "el señor de las riquezas (Kubera)", "ref": "kubera", "analisis": "vitta (riqueza) + īśa (señor)"}, {"iast": "yakṣa-rakṣasām", "sa": "यक्षरक्षसाम्", "gram": "gen. pl. m. comp.", "es": "entre los yakṣas y los rākṣasas", "ref": "kubera", "analisis": "yakṣa + rakṣas"}, {"iast": "vasūnām", "sa": "वसूनाम्", "gram": "gen. pl. m.", "es": "entre los Vasus", "ref": "vasu"}, {"iast": "pāvakaḥ", "sa": "पावकः", "gram": "nom. sg. m.", "es": "Pāvaka (Agni)", "ref": "agni", "analisis": "√pū (purificar): «el purificador»"}, {"iast": "meruḥ", "sa": "मेरुः", "gram": "nom. sg. m.", "es": "el Meru", "ref": "meru"}, {"iast": "śikhariṇām", "sa": "शिखरिणाम्", "gram": "gen. pl. m.", "es": "entre los montes", "analisis": "śikharin: «el que tiene cumbres»"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg.", "es": "yo"}], "nota": "<p>Los <em>Rudra</em> son un grupo de dioses, hijos o formas de Rudra, que los textos posteriores cuentan en once; entre ellos el principal es Śaṅkara, «el que trae el bien», es decir, Śiva. No hay que confundirlo con <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, el comentarista, que lleva su nombre. El «señor de las riquezas» es Kubera, rey de los <em>yakṣas</em>. Los <em>Vasu</em> son ocho dioses de los elementos; uno de ellos es el fuego, aquí llamado <em>Pāvaka</em>, «el purificador», es decir, <a class=\"t\" href=\"glosario.html#agni\" data-t=\"agni\">Agni</a>. El Meru es la montaña de oro que la cosmología india pone en el centro del mundo; <em>śikharin</em>, «el que tiene cumbres», es un nombre poético del monte.</p>", "interp": [{"titulo": "Śiva entre las manifestaciones de Kṛṣṇa", "html": "<p>En una obra vaiṣṇava, Kṛṣṇa nombra a Śiva como una de sus manifestaciones: es el más alto entre los Rudras, como Viṣṇu entre los Ādityas. La Gītā no opone a los dos dioses, sino que los integra en su visión de un único Señor que se manifiesta en lo más alto de cada clase. Las tradiciones posteriores leerán la relación de modos distintos, según tengan a Viṣṇu o a Śiva por el dios supremo.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "lo-mas-alto-entre-los-dioses-y-los-sabios"}, {"n": 24, "hablante": "krsna", "sa": ["पुरोधसां च मुख्यं मां विद्धि पार्थ बृहस्पतिम् ।", "सेनानीनामहं स्कन्दः सरसामस्मि सागरः ॥२४॥"], "iast": ["purodhasāṃ ca mukhyaṃ māṃ viddhi pārtha bṛhaspatim", "senānīnām ahaṃ skandaḥ sarasām asmi sāgaraḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Y entre los sacerdotes, oh <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>, sabe que soy el principal, <a class=\"t\" href=\"glosario.html#brhaspati\" data-t=\"brhaspati\">Bṛhaspati</a>; entre los jefes de ejército soy <a class=\"t\" href=\"glosario.html#skanda\" data-t=\"skanda\">Skanda</a>; entre las aguas soy el océano.</span>", "palabras": [{"iast": "purodhasām", "sa": "पुरोधसाम्", "gram": "gen. pl. m.", "es": "entre los sacerdotes (de las casas reales)", "analisis": "purodhas = purohita: «el que se pone delante», el sacerdote de la casa de un rey"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "mukhyam", "sa": "मुख्यम्", "gram": "ac. sg. m.", "es": "el principal"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg.", "es": "a mí"}, {"iast": "viddhi", "sa": "विद्धि", "gram": "2 sg. impv.", "es": "sabe, considera", "analisis": "√vid (saber)"}, {"iast": "pārtha", "sa": "पार्थ", "gram": "voc. sg. m.", "es": "oh Pārtha (Arjuna)", "ref": "partha"}, {"iast": "bṛhaspatim", "sa": "बृहस्पतिम्", "gram": "ac. sg. m.", "es": "Bṛhaspati", "ref": "brhaspati"}, {"iast": "senānīnām", "sa": "सेनानीनाम्", "gram": "gen. pl. m.", "es": "entre los jefes de ejército", "analisis": "senā (ejército) + nī (que guía)"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg.", "es": "yo"}, {"iast": "skandaḥ", "sa": "स्कन्दः", "gram": "nom. sg. m.", "es": "Skanda", "ref": "skanda"}, {"iast": "sarasām", "sa": "सरसाम्", "gram": "gen. pl. n.", "es": "entre las aguas, entre los depósitos de agua"}, {"iast": "asmi", "sa": "अस्मि", "gram": "1 sg. pres.", "es": "soy"}, {"iast": "sāgaraḥ", "sa": "सागरः", "gram": "nom. sg. m.", "es": "el océano"}], "nota": "<p><em>Purodhas</em> es el <em>purohita</em>, «el que se pone delante»: el sacerdote al servicio de una casa real, que oficia sus ritos y la aconseja. Bṛhaspati es el sacerdote de los dioses, el de <a class=\"t\" href=\"glosario.html#indra\" data-t=\"indra\">Indra</a>, su rey; por eso, explican <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, es el principal de todos (<a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>: por ser el sacerdote de los dioses). Skanda, hijo de Śiva, es el general del ejército de los dioses. <em>Saras</em> es, en general, una masa de agua, un lago o un estanque; entre todas, la mayor es el océano (<em>sāgara</em>).</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "lo-mas-alto-entre-los-dioses-y-los-sabios"}, {"n": 25, "hablante": "krsna", "sa": ["महर्षीणां भृगुरहं गिरामस्म्येकमक्षरम् ।", "यज्ञानां जपयज्ञोऽस्मि स्थावराणां हिमालयः ॥२५॥"], "iast": ["maharṣīṇāṃ bhṛgur ahaṃ girām asmy ekam akṣaram", "yajñānāṃ japa-yajño 'smi sthāvarāṇāṃ himālayaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Entre los grandes <a class=\"t\" href=\"glosario.html#rsi\" data-t=\"rsi\">sabios</a> soy <a class=\"t\" href=\"glosario.html#bhrgu\" data-t=\"bhrgu\">Bhṛgu</a>; entre las palabras soy la <a class=\"t\" href=\"glosario.html#om\" data-t=\"om\">sílaba única</a>; entre los <a class=\"t\" href=\"glosario.html#yajna\" data-t=\"yajna\">sacrificios</a> soy el sacrificio de la <a class=\"t\" href=\"glosario.html#mantra\" data-t=\"mantra\">recitación</a>; entre lo inmóvil, el <a class=\"t\" href=\"glosario.html#himalaya\" data-t=\"himalaya\">Himālaya</a>.</span>", "palabras": [{"iast": "mahā-ṛṣīṇām", "sa": "महर्षीणाम्", "gram": "gen. pl. m. comp.", "es": "entre los grandes sabios", "ref": "rsi", "analisis": "mahā (grande) + ṛṣi (sabio, vidente)"}, {"iast": "bhṛguḥ", "sa": "भृगुः", "gram": "nom. sg. m.", "es": "Bhṛgu", "ref": "bhrgu"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg.", "es": "yo"}, {"iast": "girām", "sa": "गिराम्", "gram": "gen. pl. f.", "es": "entre las palabras, entre las expresiones", "analisis": "gir (voz, palabra)"}, {"iast": "asmi", "sa": "अस्मि", "gram": "1 sg. pres.", "es": "soy"}, {"iast": "ekam", "sa": "एकम्", "gram": "nom. sg. n.", "es": "única, una"}, {"iast": "akṣaram", "sa": "अक्षरम्", "gram": "nom. sg. n.", "es": "la sílaba (oṃ)", "ref": "om"}, {"iast": "yajñānām", "sa": "यज्ञानाम्", "gram": "gen. pl. m.", "es": "entre los sacrificios", "ref": "yajna"}, {"iast": "japa-yajñaḥ", "sa": "जपयज्ञः", "gram": "nom. sg. m. comp.", "es": "el sacrificio de la recitación", "ref": "mantra", "analisis": "japa (recitación en voz baja de una fórmula) + yajña (sacrificio)"}, {"iast": "sthāvarāṇām", "sa": "स्थावराणाम्", "gram": "gen. pl. n.", "es": "entre lo inmóvil", "analisis": "sthāvara (lo que permanece, lo inmóvil)"}, {"iast": "himālayaḥ", "sa": "हिमालयः", "gram": "nom. sg. m.", "es": "el Himālaya", "ref": "himalaya", "analisis": "hima (nieve) + ālaya (morada)"}], "nota": "<p>Bhṛgu es uno de los grandes sabios de la tradición, antepasado del linaje de los Bhārgavas. La «sílaba única» es <a class=\"t\" href=\"glosario.html#om\" data-t=\"om\">oṃ</a>, que en <a class=\"vref\" href=\"capitulo-08.html#v13\" data-v=\"8.13\">8.13</a> es «la sílaba única que es brahman», y que ya en <a class=\"vref\" href=\"capitulo-07.html#v8\" data-v=\"7.8\">7.8</a> Kṛṣṇa decía ser en todos los Vedas. El <em>japa</em> es la recitación, en voz baja o mental, de un mantra o de un nombre divino, repetido muchas veces: un sacrificio que no necesita fuego, ofrenda ni sacerdote. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo pone por encima de los demás porque, libre de la violencia y de las otras faltas del rito, purifica como ninguno; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> no da razón. <em>Sthāvara</em>, «lo inmóvil», son las montañas, los árboles y todo lo que no se desplaza; <em>Himālaya</em> es «la morada de la nieve».</p>", "interp": [{"titulo": "El sacrificio de la recitación", "html": "<p>Que entre los sacrificios Kṛṣṇa elija el <em>japa</em> continúa una línea del libro: el sacrificio se interioriza y se hace al alcance de todos, como el sacrificio del conocimiento de <a class=\"vref\" href=\"capitulo-04.html#v33\" data-v=\"4.33\">4.33</a> o la ofrenda de una hoja o una flor de <a class=\"vref\" href=\"capitulo-09.html#v26\" data-v=\"9.26\">9.26</a>. Los tratados de dharma ya valoraban la recitación por encima de los ritos con ofrenda; la <em>Manusmṛti</em> la declara muy superior al sacrificio prescrito (2.85).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "lo-mas-alto-entre-los-dioses-y-los-sabios"}, {"n": 26, "hablante": "krsna", "sa": ["अश्वत्थः सर्ववृक्षाणां देवर्षीणां च नारदः ।", "गन्धर्वाणां चित्ररथः सिद्धानां कपिलो मुनिः ॥२६॥"], "iast": ["aśvatthaḥ sarva-vṛkṣāṇāṃ devarṣīṇāṃ ca nāradaḥ", "gandharvāṇāṃ citrarathaḥ siddhānāṃ kapilo muniḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Entre todos los árboles soy el <a class=\"t\" href=\"glosario.html#asvattha\" data-t=\"asvattha\">aśvattha</a>; entre los sabios divinos, <a class=\"t\" href=\"glosario.html#narada\" data-t=\"narada\">Nārada</a>; entre los <a class=\"t\" href=\"glosario.html#gandharva\" data-t=\"gandharva\">gandharvas</a>, Citraratha; entre los <a class=\"t\" href=\"glosario.html#siddha\" data-t=\"siddha\">perfectos</a>, el <a class=\"t\" href=\"glosario.html#muni\" data-t=\"muni\">sabio</a> <a class=\"t\" href=\"glosario.html#kapila\" data-t=\"kapila\">Kapila</a>.</span>", "palabras": [{"iast": "aśvatthaḥ", "sa": "अश्वत्थः", "gram": "nom. sg. m.", "es": "el aśvattha, la higuera sagrada", "ref": "asvattha"}, {"iast": "sarva-vṛkṣāṇām", "sa": "सर्ववृक्षाणाम्", "gram": "gen. pl. m. comp.", "es": "entre todos los árboles", "analisis": "sarva (todo) + vṛkṣa (árbol)"}, {"iast": "devarṣīṇām", "sa": "देवर्षीणाम्", "gram": "gen. pl. m. comp.", "es": "entre los sabios divinos", "ref": "rsi", "analisis": "deva (dios) + ṛṣi (vidente)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "nāradaḥ", "sa": "नारदः", "gram": "nom. sg. m.", "es": "Nārada", "ref": "narada"}, {"iast": "gandharvāṇām", "sa": "गन्धर्वाणाम्", "gram": "gen. pl. m.", "es": "entre los gandharvas", "ref": "gandharva"}, {"iast": "citrarathaḥ", "sa": "चित्ररथः", "gram": "nom. sg. m.", "es": "Citraratha", "ref": "gandharva", "analisis": "citra (vistoso) + ratha (carro): «el del carro vistoso»"}, {"iast": "siddhānām", "sa": "सिद्धानाम्", "gram": "gen. pl. m.", "es": "entre los perfectos", "ref": "siddha", "analisis": "participio de √sidh (lograr, cumplirse)"}, {"iast": "kapilaḥ", "sa": "कपिलः", "gram": "nom. sg. m.", "es": "Kapila", "ref": "kapila"}, {"iast": "muniḥ", "sa": "मुनिः", "gram": "nom. sg. m.", "es": "el sabio", "ref": "muni"}], "nota": "<p>El verso no tiene verbo: sigue la serie de <a class=\"vref\" href=\"capitulo-10.html#v25\" data-v=\"10.25\">10.25</a>, y el «soy» se sobrentiende. El <em>aśvattha</em> (<em>Ficus religiosa</em>) es la higuera sagrada de la India, la misma bajo la que, según la tradición budista, el Buddha alcanzó el despertar. <em>Devarṣi</em>, «sabio divino», es, según <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, el que, siendo dios, llegó a ser vidente (<a class=\"t\" href=\"glosario.html#rsi\" data-t=\"rsi\">ṛṣi</a>) por haber visto los mantras; Nārada es el más célebre. Los <a class=\"t\" href=\"glosario.html#gandharva\" data-t=\"gandharva\">gandharvas</a> son los músicos celestes, y Citraratha, «el del carro vistoso», su rey. Los <em>siddha</em>, «los que han logrado», son seres perfectos, dueños de poderes extraordinarios.</p>", "interp": [{"titulo": "El árbol que hay que cortar", "html": "<p>El aśvattha reaparece en <a class=\"vref\" href=\"capitulo-15.html#v1\" data-v=\"15.1\">15.1</a>–<a class=\"vref\" href=\"capitulo-15.html#v3\" data-v=\"15.3\">15.3</a> con otra figura: un árbol eterno con las raíces arriba y las ramas abajo, cuyas hojas son los himnos védicos, y que hay que cortar con el hacha firme del desapego. La imagen viene de la <a class=\"t\" href=\"glosario.html#katha-upanisad\" data-t=\"katha-upanisad\"><em>Kaṭha Upaniṣad</em></a> (6.1). Que el mismo árbol sea aquí la excelencia de los árboles y allí la imagen del mundo que ata dice algo del capítulo 10: Kṛṣṇa no está sólo en lo que hay que alcanzar, sino también en lo que hay que dejar atrás, si se lo ve como suyo.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "Kapila, el sabio del Sāṅkhya", "html": "<p>Entre los perfectos, Kṛṣṇa nombra a Kapila, a quien la tradición tiene por fundador del <a class=\"t\" href=\"glosario.html#sankhya\" data-t=\"sankhya\">Sāṅkhya</a>, la doctrina que discierne el espíritu de la naturaleza y cuyo vocabulario la Gītā emplea desde el capítulo 2. Nombrarlo aquí es reconocer esa doctrina como una de las glorias de lo divino, aunque la Gītā la integre en su propio teísmo. Los comentaristas, sin embargo, no mencionan aquí el Sāṅkhya: para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, Kapila es el primero de los que nacieron ya con la virtud, el conocimiento, el desapego y el poder en grado sumo; para <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, de los que conocen la verdad suprema desde su nacimiento; para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, el más digno de culto de los entregados al yoga.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "del-asvattha-a-yama"}, {"n": 27, "hablante": "krsna", "sa": ["उच्चैःश्रवसमश्वानां विद्धि माममृतोद्भवम् ।", "ऐरावतं गजेन्द्राणां नराणां च नराधिपम् ॥२७॥"], "iast": ["uccaiḥśravasam aśvānāṃ viddhi mām amṛtodbhavam", "airāvataṃ gajendrāṇāṃ narāṇāṃ ca narādhipam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Entre los caballos, sabe que soy <a class=\"t\" href=\"glosario.html#uccaihsravas\" data-t=\"uccaihsravas\">Uccaiḥśravas</a>, nacido del néctar; entre los elefantes reales, <a class=\"t\" href=\"glosario.html#airavata\" data-t=\"airavata\">Airāvata</a>; y entre los hombres, el rey.</span>", "palabras": [{"iast": "uccaiḥśravasam", "sa": "उच्चैःश्रवसम्", "gram": "ac. sg. m.", "es": "Uccaiḥśravas", "ref": "uccaihsravas", "analisis": "uccaiḥ (en alto) + śravas (oreja; fama): «el de orejas erguidas» o «el de gran fama»"}, {"iast": "aśvānām", "sa": "अश्वानाम्", "gram": "gen. pl. m.", "es": "entre los caballos"}, {"iast": "viddhi", "sa": "विद्धि", "gram": "2 sg. imper. act.", "es": "sabe", "analisis": "√vid (saber)"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg.", "es": "que yo soy, a mí"}, {"iast": "amṛtodbhavam", "sa": "अमृतोद्भवम्", "gram": "ac. sg. m. comp.", "es": "nacido del néctar", "analisis": "amṛta (néctar de la inmortalidad) + udbhava (nacimiento, origen)"}, {"iast": "airāvatam", "sa": "ऐरावतम्", "gram": "ac. sg. m.", "es": "Airāvata", "ref": "airavata"}, {"iast": "gajendrāṇām", "sa": "गजेन्द्राणाम्", "gram": "gen. pl. m. comp.", "es": "entre los elefantes reales", "analisis": "gaja (elefante) + indra (señor, el mejor)"}, {"iast": "narāṇām", "sa": "नराणाम्", "gram": "gen. pl. m.", "es": "entre los hombres"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "narādhipam", "sa": "नराधिपम्", "gram": "ac. sg. m. comp.", "es": "el rey", "analisis": "nara (hombre) + adhipa (señor)"}], "nota": "<p><em>Amṛtodbhava</em>, «nacido del néctar» (<em>amṛta</em>), alude al relato del batido del océano: dioses y demonios batieron el océano de leche para obtener el néctar de la inmortalidad, y de él surgieron, entre otros prodigios, el caballo <a class=\"t\" href=\"glosario.html#uccaihsravas\" data-t=\"uccaihsravas\">Uccaiḥśravas</a> y el elefante <a class=\"t\" href=\"glosario.html#airavata\" data-t=\"airavata\">Airāvata</a>, que la tradición da a <a class=\"t\" href=\"glosario.html#indra\" data-t=\"indra\">Indra</a> (aunque el <em>Bhāgavata</em> dice que el caballo lo tomó Bali) (<a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> extienden «nacido del néctar» también al elefante; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lo explica en cambio como «hijo de Irāvatī»). <em>Gajendra</em>, literalmente «señor de los elefantes», designa a los elefantes de rango real. <em>Narādhipa</em>, «señor de los hombres», es el rey.</p>", "interp": [{"titulo": "Entre los hombres, el rey", "html": "<p>La serie pasa de los animales prodigiosos al mundo humano, y lo excelente entre los hombres es el rey. Para un público de guerreros y príncipes, como Arjuna, la realeza era la forma más visible de la gloria; la Gītā ya había hecho de los reyes sabios (<a class=\"t\" href=\"glosario.html#rajarsi\" data-t=\"rajarsi\">rājarṣi</a>) los primeros depositarios de su enseñanza (<a class=\"vref\" href=\"capitulo-04.html#v2\" data-v=\"4.2\">4.2</a>), y los nombrará de nuevo entre los que alcanzan la meta (<a class=\"vref\" href=\"capitulo-09.html#v33\" data-v=\"9.33\">9.33</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "del-asvattha-a-yama"}, {"n": 28, "hablante": "krsna", "sa": ["आयुधानामहं वज्रं धेनूनामस्मि कामधुक् ।", "प्रजनश्चास्मि कन्दर्पः सर्पाणामस्मि वासुकिः ॥२८॥"], "iast": ["āyudhānām ahaṃ vajraṃ dhenūnām asmi kāmadhuk", "prajanaś cāsmi kandarpaḥ sarpāṇām asmi vāsukiḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Entre las armas soy el <a class=\"t\" href=\"glosario.html#vajra\" data-t=\"vajra\">rayo</a>; entre las vacas soy <a class=\"t\" href=\"glosario.html#kamadhenu\" data-t=\"kamadhenu\">Kāmadhuk</a>; soy <a class=\"t\" href=\"glosario.html#kandarpa\" data-t=\"kandarpa\">Kandarpa</a>, el que engendra; entre las serpientes soy <a class=\"t\" href=\"glosario.html#vasuki\" data-t=\"vasuki\">Vāsuki</a>.</span>", "palabras": [{"iast": "āyudhānām", "sa": "आयुधानाम्", "gram": "gen. pl. n.", "es": "entre las armas"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg.", "es": "yo"}, {"iast": "vajram", "sa": "वज्रम्", "gram": "nom. sg. n.", "es": "el rayo", "ref": "vajra"}, {"iast": "dhenūnām", "sa": "धेनूनाम्", "gram": "gen. pl. f.", "es": "entre las vacas"}, {"iast": "asmi", "sa": "अस्मि", "gram": "1 sg. pres.", "es": "soy", "analisis": "√as (ser)"}, {"iast": "kāmadhuk", "sa": "कामधुक्", "gram": "nom. sg. f.", "es": "Kāmadhuk, la vaca de los deseos", "ref": "kamadhenu", "analisis": "kāma (deseo) + duh (que da leche): «la que da a ordeñar los deseos»"}, {"iast": "prajanaḥ", "sa": "प्रजनः", "gram": "nom. sg. m.", "es": "el que engendra", "analisis": "pra + √jan (engendrar, nacer)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "kandarpaḥ", "sa": "कन्दर्पः", "gram": "nom. sg. m.", "es": "Kandarpa, el dios del amor", "ref": "kandarpa"}, {"iast": "sarpāṇām", "sa": "सर्पाणाम्", "gram": "gen. pl. m.", "es": "entre las serpientes", "analisis": "de √sṛp (reptar)"}, {"iast": "vāsukiḥ", "sa": "वासुकिः", "gram": "nom. sg. m.", "es": "Vāsuki", "ref": "vasuki"}], "nota": "<p>El <em>vajra</em>, el rayo, es el arma de <a class=\"t\" href=\"glosario.html#indra\" data-t=\"indra\">Indra</a>. <em>Kāmadhuk</em>, «la que da a ordeñar los deseos», es la vaca que concede cuanto se le pide. <em>Prajana</em>, «el que engendra»: de todos los amores, Kṛṣṇa se nombra en el que da origen a la vida. <em>Sarpa</em>, «serpiente», de √sṛp, «reptar»; en el verso siguiente aparecen los <em>nāga</em>, y los comentaristas los distinguen de distintos modos: para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, las serpientes tienen una sola cabeza y los nāgas muchas; para <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, las serpientes son venenosas y los nāgas no; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> sólo dicen que son clases distintas.</p>", "interp": [{"titulo": "El deseo que engendra", "html": "<p>En <a class=\"vref\" href=\"capitulo-03.html#v37\" data-v=\"3.37\">3.37</a>–<a class=\"vref\" href=\"capitulo-03.html#v43\" data-v=\"3.43\">3.43</a> el deseo (<a class=\"t\" href=\"glosario.html#kama\" data-t=\"kama\">kāma</a>) era el gran enemigo, y aquí Kṛṣṇa se nombra en Kandarpa, el dios del amor. No hay contradicción: ya en <a class=\"vref\" href=\"capitulo-07.html#v11\" data-v=\"7.11\">7.11</a> se había dicho «en los seres soy el deseo que no se opone al dharma». El adjetivo <em>prajana</em> concreta cuál: el deseo que engendra, el que hace nacer a los seres, no, precisan <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, el que sólo busca el placer (que para Śrīdhara va contra las escrituras); <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> glosa sólo «el que engendra» (<em>prajanayitā</em>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Entre las armas soy el rayo; entre las vacas soy Kāmadhuk; soy el deseo que engendra la vida; entre las serpientes soy Vāsuki.", "nota": "<p><em>Kandarpa</em> es el nombre del dios del amor, pero también, por extensión, el deseo amoroso mismo. La traducción principal conserva el nombre propio, como en el resto de la serie; la alternativa lo lee como el deseo, con <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, y el adjetivo <em>prajana</em>, «que engendra», lo restringe al que da vida: no el deseo del mero placer, sino el que hace nacer a los hijos.</p>"}], "ens": "del-asvattha-a-yama"}, {"n": 29, "hablante": "krsna", "sa": ["अनन्तश्चास्मि नागानां वरुणो यादसामहम् ।", "पितॄणामर्यमा चास्मि यमः संयमतामहम् ॥२९॥"], "iast": ["anantaś cāsmi nāgānāṃ varuṇo yādasām aham", "pitṝṇām aryamā cāsmi yamaḥ saṃyamatām aham"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Entre los nāgas soy <a class=\"t\" href=\"glosario.html#ananta\" data-t=\"ananta\">Ananta</a>; entre los seres de las aguas soy <a class=\"t\" href=\"glosario.html#varuna\" data-t=\"varuna\">Varuṇa</a>; entre los <a class=\"t\" href=\"glosario.html#pitr\" data-t=\"pitr\">antepasados</a> soy <a class=\"t\" href=\"glosario.html#aryaman\" data-t=\"aryaman\">Aryaman</a>; y entre los que someten soy <a class=\"t\" href=\"glosario.html#yama\" data-t=\"yama\">Yama</a>.</span>", "palabras": [{"iast": "anantaḥ", "sa": "अनन्तः", "gram": "nom. sg. m.", "es": "Ananta", "ref": "ananta", "analisis": "an (no) + anta (fin): «el sin fin»"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "asmi", "sa": "अस्मि", "gram": "1 sg. pres.", "es": "soy", "analisis": "√as (ser)"}, {"iast": "nāgānām", "sa": "नागानाम्", "gram": "gen. pl. m.", "es": "entre los nāgas, las serpientes divinas"}, {"iast": "varuṇaḥ", "sa": "वरुणः", "gram": "nom. sg. m.", "es": "Varuṇa", "ref": "varuna"}, {"iast": "yādasām", "sa": "यादसाम्", "gram": "gen. pl. n.", "es": "entre los seres de las aguas"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg.", "es": "yo"}, {"iast": "pitṝṇām", "sa": "पितॄणाम्", "gram": "gen. pl. m.", "es": "entre los antepasados", "ref": "pitr"}, {"iast": "aryamā", "sa": "अर्यमा", "gram": "nom. sg. m.", "es": "Aryaman", "ref": "aryaman"}, {"iast": "yamaḥ", "sa": "यमः", "gram": "nom. sg. m.", "es": "Yama", "ref": "yama"}, {"iast": "saṃyamatām", "sa": "संयमताम्", "gram": "gen. pl. m. part.", "es": "entre los que someten, los que refrenan", "analisis": "participio presente de saṃ + √yam (sujetar, refrenar)"}], "nota": "<p>Ananta, «el sin fin», también llamado Śeṣa, es la serpiente de mil cabezas sobre la que reposa <a class=\"t\" href=\"glosario.html#visnu\" data-t=\"visnu\">Viṣṇu</a>. <a class=\"t\" href=\"glosario.html#varuna\" data-t=\"varuna\">Varuṇa</a>, dios del orden cósmico en el Veda, es en la épica el señor de las aguas, y <em>yādas</em> son los seres que las habitan (así <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende «las divinidades de las aguas»). <a class=\"t\" href=\"glosario.html#aryaman\" data-t=\"aryaman\">Aryaman</a>, uno de los Ādityas, preside a los <a class=\"t\" href=\"glosario.html#pitr\" data-t=\"pitr\">antepasados</a>. <a class=\"t\" href=\"glosario.html#yama\" data-t=\"yama\">Yama</a>, hijo de <a class=\"t\" href=\"glosario.html#vivasvat\" data-t=\"vivasvat\">Vivasvat</a>, es el señor de los muertos. <em>Saṃyamatām</em>, «de los que sujetan», no dice qué se sujeta; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> entienden a los demás: Yama es el que somete y castiga. Leerlo como dominio de sí, el sentido de <em>saṃyama</em> en el yoga, sería posible por la palabra, pero ningún comentarista lo hace.</p>", "interp": [{"titulo": "El que pone límite", "html": "<p>La serie de este verso recorre los guardianes del orden: Ananta, que en la imagen tradicional sostiene el mundo; Varuṇa, que en el Veda vigila el orden cósmico; Aryaman, que preside a los muertos honrados por sus descendientes; y Yama, que juzga a todos. Que la muerte misma figure entre las glorias de Kṛṣṇa anticipa lo que se dirá en <a class=\"vref\" href=\"capitulo-10.html#v34\" data-v=\"10.34\">10.34</a> («soy la muerte que todo lo arrebata») y lo que Arjuna verá en la forma universal (<a class=\"vref\" href=\"capitulo-11.html#v32\" data-v=\"11.32\">11.32</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "del-asvattha-a-yama"}, {"n": 30, "hablante": "krsna", "sa": ["प्रह्लादश्चास्मि दैत्यानां कालः कलयतामहम् ।", "मृगाणां च मृगेन्द्रोऽहं वैनतेयश्च पक्षिणाम् ॥३०॥"], "iast": ["prahlādaś cāsmi daityānāṃ kālaḥ kalayatām aham", "mṛgāṇāṃ ca mṛgendro 'haṃ vainateyaś ca pakṣiṇām"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Entre los <a class=\"t\" href=\"glosario.html#daitya\" data-t=\"daitya\">daityas</a> soy <a class=\"t\" href=\"glosario.html#prahlada\" data-t=\"prahlada\">Prahlāda</a>; entre los que cuentan, el <a class=\"t\" href=\"glosario.html#kala\" data-t=\"kala\">tiempo</a>; entre las fieras, el león; y entre las aves, <a class=\"t\" href=\"glosario.html#garuda\" data-t=\"garuda\">el hijo de Vinatā</a>.</span>", "palabras": [{"iast": "prahlādaḥ", "sa": "प्रह्लादः", "gram": "nom. sg. m.", "es": "Prahlāda", "ref": "prahlada"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "asmi", "sa": "अस्मि", "gram": "1 sg. pres.", "es": "soy", "analisis": "√as (ser)"}, {"iast": "daityānām", "sa": "दैत्यानाम्", "gram": "gen. pl. m.", "es": "de (entre) los daityas", "ref": "daitya", "analisis": "daitya (descendiente de Diti)"}, {"iast": "kālaḥ", "sa": "कालः", "gram": "nom. sg. m.", "es": "el tiempo", "ref": "kala"}, {"iast": "kalayatām", "sa": "कलयताम्", "gram": "gen. pl. m. part. pres.", "es": "de los que cuentan", "analisis": "√kal (contar, calcular; también impeler, someter)"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "mṛgāṇām", "sa": "मृगाणाम्", "gram": "gen. pl. m.", "es": "de las fieras, de los animales salvajes"}, {"iast": "mṛgendraḥ", "sa": "मृगेन्द्रः", "gram": "nom. sg. m. comp.", "es": "el rey de las fieras, el león", "analisis": "mṛga (animal salvaje) + indra (señor, rey)"}, {"iast": "vainateyaḥ", "sa": "वैनतेयः", "gram": "nom. sg. m.", "es": "el hijo de Vinatā", "ref": "garuda", "analisis": "patronímico de Vinatā, madre de Garuḍa"}, {"iast": "pakṣiṇām", "sa": "पक्षिणाम्", "gram": "gen. pl. m.", "es": "de las aves", "analisis": "pakṣin (el que tiene alas)"}], "nota": "<p>Con este verso la lista llega a los demonios, a las fieras y a las aves: en cada clase, aun en la de los enemigos de los dioses, hay algo que sobresale. <em>Daitya</em>: «descendiente de Diti», una de las estirpes de los enemigos de los dioses (véase la ficha <a class=\"t\" href=\"glosario.html#daitya\" data-t=\"daitya\">daitya</a>). <em>Mṛgendra</em>, «el señor de las fieras», es el león (<a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> admite también el tigre). <em>Vainateya</em>, «el hijo de Vinatā», es <a class=\"t\" href=\"glosario.html#garuda\" data-t=\"garuda\">Garuḍa</a>, el ave sobre la que cabalga Viṣṇu. El tiempo (<em>kāla</em>) vuelve en <a class=\"vref\" href=\"capitulo-10.html#v33\" data-v=\"10.33\">10.33</a> como «el tiempo imperecedero».</p>", "interp": [{"titulo": "El mejor de los demonios", "html": "<p>La primera manifestación del verso es una paradoja buscada: lo más alto entre los daityas, los enemigos de los dioses, es <a class=\"t\" href=\"glosario.html#prahlada\" data-t=\"prahlada\">Prahlāda</a>, que fue, según los Purāṇas, un devoto de Viṣṇu desde niño, perseguido por su propio padre por esa devoción. La lista no elige al más poderoso de su clase, sino al que en ella deja ver mejor lo divino; así, la manifestación de Kṛṣṇa puede aparecer incluso donde menos se espera. <a class=\"t\" href=\"glosario.html#garuda\" data-t=\"garuda\">Garuḍa</a>, al final del verso, cierra el contraste: el ave que lleva a Viṣṇu.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Entre los daityas soy Prahlāda; entre los que someten, el tiempo; entre las fieras, el león; y entre las aves, el hijo de Vinatā.", "nota": "<p><em>Kalayatām</em> es el participio de √<em>kal</em>, que vale «contar, calcular, medir» y también «impeler, llevar consigo, someter». La traducción principal toma el primer sentido, con <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> («los que cuentan»): el tiempo es la medida de todo lo que se cuenta (instantes, días, años). <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> toma también el sentido de «contar», pero no entiende el tiempo: «entre los que cuentan con ánimo de dañar, soy Kāla, la muerte»; Vedānta Deśika precisa que es un ser personal, distinto de Yama y del tiempo imperecedero de <a class=\"vref\" href=\"capitulo-10.html#v33\" data-v=\"10.33\">10.33</a>. La alternativa toma el segundo, que <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> da en primer lugar («los que someten», o bien «los que cuentan»): el tiempo es lo que acaba sometiéndolo todo, como dirá Kṛṣṇa en <a class=\"vref\" href=\"capitulo-11.html#v32\" data-v=\"11.32\">11.32</a> («soy el tiempo que destruye los mundos»).</p>"}]}, {"n": 31, "hablante": "krsna", "sa": ["पवनः पवतामस्मि रामः शस्त्रभृतामहम् ।", "झषाणां मकरश्चास्मि स्रोतसामस्मि जाह्नवी ॥३१॥"], "iast": ["pavanaḥ pavatām asmi rāmaḥ śastra-bhṛtām aham", "jhaṣāṇāṃ makaraś cāsmi srotasām asmi jāhnavī"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Entre los que purifican soy el viento; entre los que llevan armas, <a class=\"t\" href=\"glosario.html#rama\" data-t=\"rama\">Rāma</a>; entre los peces, el <a class=\"t\" href=\"glosario.html#makara\" data-t=\"makara\">makara</a>; y entre los ríos, la <a class=\"t\" href=\"glosario.html#ganga\" data-t=\"ganga\">Jāhnavī</a>.</span>", "palabras": [{"iast": "pavanaḥ", "sa": "पवनः", "gram": "nom. sg. m.", "es": "el viento", "analisis": "√pū (purificar): «el que purifica»"}, {"iast": "pavatām", "sa": "पवताम्", "gram": "gen. pl. m. part. pres.", "es": "de los que purifican", "analisis": "√pū (purificar)"}, {"iast": "asmi", "sa": "अस्मि", "gram": "1 sg. pres.", "es": "soy"}, {"iast": "rāmaḥ", "sa": "रामः", "gram": "nom. sg. m.", "es": "Rāma", "ref": "rama"}, {"iast": "śastra-bhṛtām", "sa": "शस्त्रभृताम्", "gram": "gen. pl. m. comp.", "es": "de los que llevan armas", "analisis": "śastra (arma) + bhṛt (el que lleva; √bhṛ)"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "jhaṣāṇām", "sa": "झषाणाम्", "gram": "gen. pl. m.", "es": "de los peces, de los seres acuáticos"}, {"iast": "makaraḥ", "sa": "मकरः", "gram": "nom. sg. m.", "es": "el makara", "ref": "makara"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "srotasām", "sa": "स्रोतसाम्", "gram": "gen. pl. n.", "es": "de las corrientes, de los ríos", "analisis": "srotas (corriente; √sru, fluir)"}, {"iast": "jāhnavī", "sa": "जाह्नवी", "gram": "nom. sg. f.", "es": "la Jāhnavī, el Ganges", "ref": "ganga", "analisis": "«la hija de Jahnu»"}], "nota": "<p><em>Pavana</em>, «el viento», es literalmente «el que purifica» (√<em>pū</em>), y <em>pavatām</em> juega con la misma raíz: entre los que purifican, el que purifica por excelencia (así <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>; <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> admiten también «entre los veloces», y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> entiende «entre los que se mueven»). <em>Śastra-bhṛt</em>: «el que lleva armas», el guerrero. <em>Makara</em>: un gran animal acuático, cocodrilo o monstruo marino según los textos (véase la ficha). <em>Jāhnavī</em>, «la hija de Jahnu», es el Ganges (<a class=\"t\" href=\"glosario.html#ganga\" data-t=\"ganga\">Gaṅgā</a>): según el relato, el rey Jahnu se bebió el río cuando éste inundó su lugar de sacrificio, y lo dejó salir después por la oreja.</p>", "interp": [{"titulo": "Qué Rāma", "html": "<p>El verso no dice qué Rāma es «el mejor de los que llevan armas». <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo entienden de Rāma, el hijo de Daśaratha y héroe del <em>Rāmāyaṇa</em>, modelo del rey y del guerrero justo, y también <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, que admite como alternativa a Paraśurāma, «Rāma el del hacha»; <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> no lo precisa, aunque Vedānta Deśika, en su escuela, piensa en el que mató a Rāvaṇa; Viśvanātha Cakravartī, de la tradición <a class=\"t\" href=\"glosario.html#gaudiya\" data-t=\"gaudiya\">gauḍīya</a>, piensa en Paraśurāma, y para <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a> Rāma es aquí el Señor mismo. Ninguno piensa en Balarāma, el hermano de Kṛṣṇa, que también lleva el nombre. Sea cual sea, el verso da un rasgo curioso: Kṛṣṇa, que es él mismo un descenso de Viṣṇu, nombra como manifestación suya a otro. <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> sortea la dificultad: la manifestación no sería aquí Rāma mismo, sino su condición de portador de armas (como en <a class=\"vref\" href=\"capitulo-10.html#v37\" data-v=\"10.37\">10.37</a> lo es, en Vāsudeva, el ser hijo de Vasudeva); y para <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, que explica el nombre como «el que es dicha plena y deleita al mundo», Rāma es el Señor mismo, no una manifestación más. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo explica: los descensos, aunque tienen todo el poder divino, entran en la lista para que se medite en el Señor bajo esa forma, como él mismo se nombra entre los Vṛṣṇis (<a class=\"vref\" href=\"capitulo-10.html#v37\" data-v=\"10.37\">10.37</a>); para <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, se nombran sólo para señalar su poder excepcional.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 32, "hablante": "krsna", "sa": ["सर्गाणामादिरन्तश्च मध्यं चैवाहमर्जुन ।", "अध्यात्मविद्या विद्यानां वादः प्रवदतामहम् ॥३२॥"], "iast": ["sargāṇām ādir antaś ca madhyaṃ caivāham arjuna", "adhyātma-vidyā vidyānāṃ vādaḥ pravadatām aham"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">De las creaciones soy el principio, el fin y también el medio, oh <a class=\"t\" href=\"glosario.html#arjuna\" data-t=\"arjuna\">Arjuna</a>; entre los saberes, el <a class=\"t\" href=\"glosario.html#adhyatma\" data-t=\"adhyatma\">saber del sí-mismo</a>; y de los que discuten, la discusión.</span>", "palabras": [{"iast": "sargāṇām", "sa": "सर्गाणाम्", "gram": "gen. pl. m.", "es": "de las creaciones", "analisis": "sarga (emisión, creación; √sṛj)"}, {"iast": "ādiḥ", "sa": "आदिः", "gram": "nom. sg. m.", "es": "el principio"}, {"iast": "antaḥ", "sa": "अन्तः", "gram": "nom. sg. m.", "es": "el fin"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "madhyam", "sa": "मध्यम्", "gram": "nom. sg. n.", "es": "el medio"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "también, precisamente"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "arjuna", "sa": "अर्जुन", "gram": "voc. sg. m.", "es": "oh Arjuna", "ref": "arjuna"}, {"iast": "adhyātma-vidyā", "sa": "अध्यात्मविद्या", "gram": "nom. sg. f. comp.", "es": "el saber del sí-mismo", "ref": "adhyatma", "analisis": "adhyātma (lo relativo al sí-mismo) + vidyā (saber)"}, {"iast": "vidyānām", "sa": "विद्यानाम्", "gram": "gen. pl. f.", "es": "de los saberes"}, {"iast": "vādaḥ", "sa": "वादः", "gram": "nom. sg. m.", "es": "la discusión", "analisis": "√vad (hablar): la discusión que busca la verdad"}, {"iast": "pravadatām", "sa": "प्रवदताम्", "gram": "gen. pl. m. part. pres.", "es": "de los que discuten", "analisis": "pra-√vad (hablar, disputar)"}], "nota": "<p>El verso amplía lo dicho en <a class=\"vref\" href=\"capitulo-10.html#v20\" data-v=\"10.20\">10.20</a>, donde Kṛṣṇa se dice «el principio, el medio y el fin de los seres»; aquí, explica <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, lo dice de todas las creaciones (<em>sarga</em>), y no sólo de los seres animados (<a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>: aquí, de las creaciones inertes). <em>Adhyātma-vidyā</em>, «el saber del sí-mismo», es el conocimiento de lo que el capítulo 8 llamó <em>adhyātma</em>, «lo relativo al sí-mismo» (<a class=\"vref\" href=\"capitulo-08.html#v3\" data-v=\"8.3\">8.3</a>) y que conduce a la liberación.</p>", "interp": [{"titulo": "Discutir para saber", "html": "<p>La lógica india (Nyāya) distingue tres maneras de discutir. En el <em>vāda</em>, los dos interlocutores buscan juntos la verdad; en el <em>jalpa</em>, cada uno quiere imponerse por cualquier medio; en la <em>vitaṇḍā</em>, uno se limita a refutar sin defender nada (<em>Nyāya-sūtra</em> 1.2.1–1.2.3). Así leen el verso los comentaristas (<a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> nombran la tríada; <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> la definen, éste citando el <em>Nyāya-sūtra</em>), y en este sentido técnico lo que Kṛṣṇa reconoce como suyo no es el gusto por la polémica, sino la discusión que sirve al conocimiento; y la Gītā entera, un diálogo de preguntas y respuestas, sería un ejemplo de ella.</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "De las creaciones soy el principio, el fin y también el medio, oh Arjuna; entre los saberes, el saber del sí-mismo; y entre las maneras de discutir, la discusión que busca la verdad.", "nota": "<p><em>Pravadatām</em> es literalmente «de los que discuten». La alternativa hace explícito el sentido que el término <em>vāda</em> tiene en la tradición de la lógica india, y en el que lo leen aquí <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>: la discusión honesta, que busca establecer la verdad, frente a la que sólo quiere ganar (<em>jalpa</em>) y a la que sólo quiere refutar (<em>vitaṇḍā</em>) (véase la interpretación). La traducción principal conserva la concisión del original.</p>"}]}, {"n": 33, "hablante": "krsna", "sa": ["अक्षराणामकारोऽस्मि द्वन्द्वः सामासिकस्य च ।", "अहमेवाक्षयः कालो धाताहं विश्वतोमुखः ॥३३॥"], "iast": ["akṣarāṇām akāro 'smi dvandvaḥ sāmāsikasya ca", "aham evākṣayaḥ kālo dhātāhaṃ viśvato-mukhaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Entre las letras soy la A, y entre los compuestos, el <a class=\"t\" href=\"glosario.html#dvandva\" data-t=\"dvandva\">copulativo</a>. Yo soy también el <a class=\"t\" href=\"glosario.html#kala\" data-t=\"kala\">tiempo</a> imperecedero; yo, el que dispone, con el rostro vuelto a todas partes.</span>", "palabras": [{"iast": "akṣarāṇām", "sa": "अक्षराणाम्", "gram": "gen. pl. n.", "es": "de las letras", "ref": "aksara", "analisis": "akṣara (sílaba, letra; también «lo imperecedero»)"}, {"iast": "akāraḥ", "sa": "अकारः", "gram": "nom. sg. m.", "es": "la letra A", "analisis": "a + kāra (sufijo con que se nombran los sonidos)"}, {"iast": "asmi", "sa": "अस्मि", "gram": "1 sg. pres.", "es": "soy"}, {"iast": "dvandvaḥ", "sa": "द्वन्द्वः", "gram": "nom. sg. m.", "es": "el compuesto copulativo", "ref": "dvandva", "analisis": "dvandva (pareja)"}, {"iast": "sāmāsikasya", "sa": "सामासिकस्य", "gram": "gen. sg. n.", "es": "del conjunto de los compuestos", "analisis": "sāmāsika (lo relativo a los compuestos, samāsa)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "precisamente, también"}, {"iast": "akṣayaḥ", "sa": "अक्षयः", "gram": "nom. sg. m.", "es": "imperecedero", "analisis": "a (no) + kṣaya (destrucción)"}, {"iast": "kālaḥ", "sa": "कालः", "gram": "nom. sg. m.", "es": "el tiempo", "ref": "kala"}, {"iast": "dhātā", "sa": "धाता", "gram": "nom. sg. m.", "es": "el que dispone, el que sostiene", "analisis": "√dhā (poner, disponer, sostener)"}, {"iast": "viśvato-mukhaḥ", "sa": "विश्वतोमुखः", "gram": "nom. sg. m. comp.", "es": "con el rostro vuelto a todas partes", "analisis": "viśvataḥ (por todas partes) + mukha (rostro)"}], "nota": "<p>Dos manifestaciones tomadas de la gramática. La A es la primera letra del alfabeto sánscrito y, además, la vocal que va implícita en cada consonante: una <em>k</em> escrita sola se lee <em>ka</em>; por eso puede decirse que está en todas las letras. El <em>dvandva</em> es el compuesto copulativo, el que une dos o más términos del mismo rango, como <em>rāma-lakṣmaṇau</em>, «Rāma y Lakṣmaṇa»: a diferencia de otros compuestos, ninguno de sus miembros se subordina al otro, y por eso lo tienen por el mejor <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>. <em>Akṣara</em>, «letra», es la misma palabra que en <a class=\"vref\" href=\"capitulo-08.html#v3\" data-v=\"8.3\">8.3</a> designa «lo imperecedero». El tiempo de este verso, «imperecedero» (<em>akṣaya</em>), no es ya el que se cuenta de <a class=\"vref\" href=\"capitulo-10.html#v30\" data-v=\"10.30\">10.30</a>, sino el que lo abarca todo: el tiempo como flujo sin fin, frente al que mide la vida de cada uno (<a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>), o el Señor mismo, «tiempo del tiempo» (<a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> da las dos lecturas: el tiempo ordinario, que no se agota, o el Señor); anuncia <a class=\"vref\" href=\"capitulo-11.html#v32\" data-v=\"11.32\">11.32</a>.</p>", "interp": [{"titulo": "La letra que está en todas", "html": "<p>Un viejo dicho de la tradición védica, que citan aquí <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> (<em>akāro vai sarvā vāk</em>), afirma que «la A es toda la palabra», porque sin ella no se pronuncia ninguna otra letra. La Gītā aplica esa idea a Kṛṣṇa: como la A en el alfabeto, él está presente en todo, sin ser una cosa más entre las otras. La imagen del compuesto copulativo dice algo parecido de otro modo: en el <em>dvandva</em> los miembros están juntos sin que uno absorba al otro.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Entre las letras soy la A, y entre los compuestos, el copulativo. Yo soy también el tiempo imperecedero; yo, el que da a cada uno el fruto de sus actos, presente en todas partes.", "nota": "<p><em>Dhātṛ</em> es «el que pone, dispone, sostiene» (√<em>dhā</em>). La traducción principal lo deja en ese sentido general; la alternativa lo concreta como «el que dispensa el fruto de las acciones», que es como la glosan aquí <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, y los dos primeros también en <a class=\"vref\" href=\"capitulo-09.html#v17\" data-v=\"9.17\">9.17</a>, donde la edición la tradujo «el que lo sostiene»; <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> entiende aquí a Brahmā, el creador de cuatro rostros. <em>Viśvato-mukha</em>, «con el rostro en todas partes», es la misma imagen de <a class=\"vref\" href=\"capitulo-09.html#v15\" data-v=\"9.15\">9.15</a>: el que todo lo ve porque está presente en todo.</p>"}], "ens": "el-tiempo-que-todo-lo-arrebata"}, {"n": 34, "hablante": "krsna", "sa": ["मृत्युः सर्वहरश्चाहमुद्भवश्च भविष्यताम् ।", "कीर्तिः श्रीर्वाक्च नारीणां स्मृतिर्मेधा धृतिः क्षमा ॥३४॥"], "iast": ["mṛtyuḥ sarva-haraś cāham udbhavaś ca bhaviṣyatām", "kīrtiḥ śrīr vāk ca nārīṇāṃ smṛtir medhā dhṛtiḥ kṣamā"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Soy la muerte que todo lo arrebata, y el origen de lo que ha de ser; y, entre las mujeres, la <a class=\"t\" href=\"glosario.html#kirti\" data-t=\"kirti\">fama</a>, la <a class=\"t\" href=\"glosario.html#sri\" data-t=\"sri\">fortuna</a>, la palabra, la memoria, la inteligencia, la firmeza y la paciencia.</span>", "palabras": [{"iast": "mṛtyuḥ", "sa": "मृत्युः", "gram": "nom. sg. m.", "es": "la muerte"}, {"iast": "sarva-haraḥ", "sa": "सर्वहरः", "gram": "nom. sg. m. comp.", "es": "que todo lo arrebata", "analisis": "sarva (todo) + hara (el que lleva, arrebata; √hṛ)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "udbhavaḥ", "sa": "उद्भवः", "gram": "nom. sg. m.", "es": "el origen, el surgir", "analisis": "ud-√bhū (surgir)"}, {"iast": "bhaviṣyatām", "sa": "भविष्यताम्", "gram": "gen. pl. part. fut.", "es": "de lo que ha de ser", "analisis": "√bhū (ser, llegar a ser)"}, {"iast": "kīrtiḥ", "sa": "कीर्तिः", "gram": "nom. sg. f.", "es": "la fama", "ref": "kirti"}, {"iast": "śrīḥ", "sa": "श्रीः", "gram": "nom. sg. f.", "es": "la fortuna, el esplendor", "ref": "sri"}, {"iast": "vāk", "sa": "वाक्", "gram": "nom. sg. f.", "es": "la palabra"}, {"iast": "nārīṇām", "sa": "नारीणाम्", "gram": "gen. pl. f.", "es": "de las femeninas, de las mujeres"}, {"iast": "smṛtiḥ", "sa": "स्मृतिः", "gram": "nom. sg. f.", "es": "la memoria", "analisis": "√smṛ (recordar)"}, {"iast": "medhā", "sa": "मेधा", "gram": "nom. sg. f.", "es": "la inteligencia"}, {"iast": "dhṛtiḥ", "sa": "धृतिः", "gram": "nom. sg. f.", "es": "la firmeza", "analisis": "√dhṛ (sostener)"}, {"iast": "kṣamā", "sa": "क्षमा", "gram": "nom. sg. f.", "es": "la paciencia, la capacidad de perdonar"}], "nota": "<p><em>Sarva-hara</em>, «el que todo lo arrebata», es un nombre de la muerte, que a todos se lleva; y Kṛṣṇa es a la vez lo contrario, el origen de lo que todavía ha de nacer (así <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> entienden en cambio <em>udbhava</em> como la prosperidad de los que están destinados a la buena fortuna): los dos extremos de la existencia de cada ser. La segunda mitad enumera siete sustantivos femeninos: <em>kīrti</em>, la fama o buena reputación; <em>śrī</em>, la fortuna, la prosperidad y el esplendor (es también el nombre de la diosa Lakṣmī; véase la ficha <a class=\"t\" href=\"glosario.html#sri\" data-t=\"sri\">śrī</a>); <em>vāk</em>, la palabra; <em>smṛti</em>, la memoria (aquí no es la tradición textual que la palabra designa en otros contextos); <em>medhā</em>, la inteligencia, la capacidad de retener lo aprendido; <em>dhṛti</em>, la firmeza o constancia; <em>kṣamā</em>, la paciencia, el perdón.</p>", "interp": [{"titulo": "Siete figuras femeninas", "html": "<p>Varias de estas cualidades son también, en los Purāṇas, figuras personificadas, y así las leen aquí <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> («siete mujeres en forma de diosas») y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> («las siete esposas de Dharma»): diosas o hijas de Dakṣa casadas con el dios Dharma, entre las que se cuentan Kīrti, Medhā o Dhṛti; y Vāk es, desde el Ṛg-veda, la diosa de la palabra. El verso puede leerse en los dos planos a la vez: como lista de virtudes y como lista de figuras que las encarnan.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "La muerte y el tiempo", "html": "<p>Con <a class=\"vref\" href=\"capitulo-10.html#v33\" data-v=\"10.33\">10.33</a>, el verso forma un pequeño núcleo dentro de la lista: Kṛṣṇa es el tiempo imperecedero y es la muerte que todo lo arrebata. Es el anuncio de lo que Arjuna verá en el capítulo siguiente, cuando Kṛṣṇa se le muestre como «el tiempo que destruye los mundos» (<a class=\"vref\" href=\"capitulo-11.html#v32\" data-v=\"11.32\">11.32</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Soy la muerte que todo lo arrebata, y el origen de lo que ha de ser; y, entre las cualidades femeninas, la fama, la fortuna, la palabra, la memoria, la inteligencia, la firmeza y la paciencia.", "nota": "<p><em>Nārīṇām</em> es literalmente «de las mujeres», y así lo entienden los comentaristas: <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, «las más excelentes de las mujeres», de las que basta un reflejo para tenerse por colmado; <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, siete mujeres en forma de diosas; <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, las siete esposas de Dharma; Vedānta Deśika defiende expresamente que no pueden ser simples cualidades, que también se dan en los hombres, y que entre ellas la más alta es Śrī. La alternativa añade «cualidades», como la traducción inglesa de Gambhīrānanda, para hacer explícito lo que tienen en común los siete términos: son nombres femeninos en sánscrito, y cada uno nombra una cualidad.</p>"}, {"html": "Soy la muerte que todo lo arrebata, y la prosperidad de los que han de prosperar; y, entre las mujeres, la fama, la fortuna, la palabra, la memoria, la inteligencia, la firmeza y la paciencia.", "nota": "<p><em>Udbhavaś ca bhaviṣyatām</em>: la traducción principal entiende «el origen de los que han de ser», como <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> entienden <em>udbhava</em> como el auge, la prosperidad de los destinados a la buena fortuna.</p>"}], "ens": "el-tiempo-que-todo-lo-arrebata"}, {"n": 35, "hablante": "krsna", "sa": ["बृहत्साम तथा साम्नां गायत्री छन्दसामहम् ।", "मासानां मार्गशीर्षोऽहमृतूनां कुसुमाकरः ॥३५॥"], "iast": ["bṛhat-sāma tathā sāmnāṃ gāyatrī chandasām aham", "māsānāṃ mārgaśīrṣo 'ham ṛtūnāṃ kusumākaraḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Entre los <a class=\"t\" href=\"glosario.html#sama-veda\" data-t=\"sama-veda\">sāmans</a> soy el Bṛhat-sāman; entre los metros, la <a class=\"t\" href=\"glosario.html#gayatri\" data-t=\"gayatri\">gāyatrī</a>; entre los meses, <a class=\"t\" href=\"glosario.html#margasirsa\" data-t=\"margasirsa\">Mārgaśīrṣa</a>; y entre las estaciones, la que trae las flores.</span>", "palabras": [{"iast": "bṛhat-sāma", "sa": "बृहत्साम", "gram": "nom. sg. n. comp.", "es": "el Bṛhat-sāman", "ref": "sama-veda", "analisis": "bṛhat (grande) + sāman (canto del Sāma-veda): «el gran sāman»"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "así, también"}, {"iast": "sāmnām", "sa": "साम्नाम्", "gram": "gen. pl. n.", "es": "de los sāmans, de los cantos", "ref": "sama-veda"}, {"iast": "gāyatrī", "sa": "गायत्री", "gram": "nom. sg. f.", "es": "la gāyatrī", "ref": "gayatri"}, {"iast": "chandasām", "sa": "छन्दसाम्", "gram": "gen. pl. n.", "es": "de los metros"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "māsānām", "sa": "मासानाम्", "gram": "gen. pl. m.", "es": "de los meses"}, {"iast": "mārgaśīrṣaḥ", "sa": "मार्गशीर्षः", "gram": "nom. sg. m.", "es": "Mārgaśīrṣa", "ref": "margasirsa"}, {"iast": "ṛtūnām", "sa": "ऋतूनाम्", "gram": "gen. pl. m.", "es": "de las estaciones"}, {"iast": "kusumākaraḥ", "sa": "कुसुमाकरः", "gram": "nom. sg. m. comp.", "es": "la que trae las flores, la primavera", "analisis": "kusuma (flor) + ākara (mina, fuente, abundancia)"}], "nota": "<p>Los <em>sāmans</em> son los cantos del <a class=\"t\" href=\"glosario.html#sama-veda\" data-t=\"sama-veda\">Sāma-veda</a>, que en <a class=\"vref\" href=\"capitulo-10.html#v22\" data-v=\"10.22\">10.22</a> Kṛṣṇa ha llamado el mejor de los Vedas; el <em>Bṛhat-sāman</em>, «el gran sāman», es uno de los más importantes de la liturgia: según <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, porque se canta sobre la estrofa <em>tvām id dhi havāmahe</em> (<em>Ṛg-veda</em> 6.46.1), que alaba a Indra como señor de todo; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> dice sólo que es el principal de los sāmans. La <a class=\"t\" href=\"glosario.html#gayatri\" data-t=\"gayatri\">gāyatrī</a> es el metro de tres versos de ocho sílabas y, por excelencia, la estrofa de ese metro que se recita cada día (<em>Ṛg-veda</em> 3.62.10). <a class=\"t\" href=\"glosario.html#margasirsa\" data-t=\"margasirsa\">Mārgaśīrṣa</a> es el mes que corresponde aproximadamente a noviembre-diciembre. <em>Kusumākara</em>, «la mina de las flores», es la primavera (<em>vasanta</em>).</p>", "interp": [{"titulo": "El calendario y la liturgia", "html": "<p>El verso recorre las formas con que se ordena el tiempo del culto: el canto, el metro, el mes y la estación. En cada una Kṛṣṇa elige lo más alto o lo más grato: el sāman mayor, el metro de la estrofa más sagrada, la estación de las flores. La elección de <a class=\"t\" href=\"glosario.html#margasirsa\" data-t=\"margasirsa\">Mārgaśīrṣa</a> es la más llamativa para un lector de hoy; su otro nombre, <em>āgrahāyaṇa</em>, recuerda que en un calendario antiguo era el mes con que empezaba el año. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> da otra razón: es el mes del arroz nuevo y de las verduras frescas, sin frío ni calor, y por eso grato; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> no dan ninguna.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 36, "hablante": "krsna", "sa": ["द्यूतं छलयतामस्मि तेजस्तेजस्विनामहम् ।", "जयोऽस्मि व्यवसायोऽस्मि सत्त्वं सत्त्ववतामहम् ॥३६॥"], "iast": ["dyūtaṃ chalayatām asmi tejas tejasvinām aham", "jayo 'smi vyavasāyo 'smi sattvaṃ sattvavatām aham"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Soy el juego de dados de los que engañan, el <a class=\"t\" href=\"glosario.html#tejas\" data-t=\"tejas\">esplendor</a> de los espléndidos; soy la victoria, soy la resolución, soy la <a class=\"t\" href=\"glosario.html#sattva\" data-t=\"sattva\">bondad</a> de los buenos.</span>", "palabras": [{"iast": "dyūtam", "sa": "द्यूतम्", "gram": "nom. sg. n.", "es": "el juego (de dados)", "analisis": "√div (jugar, apostar)"}, {"iast": "chalayatām", "sa": "छलयताम्", "gram": "gen. pl. m. part. pres.", "es": "de los que engañan", "analisis": "denominativo de chala (engaño, fraude)"}, {"iast": "asmi", "sa": "अस्मि", "gram": "1 sg. pres. act.", "es": "soy", "analisis": "√as (ser)"}, {"iast": "tejaḥ", "sa": "तेजः", "gram": "nom. sg. n.", "es": "el esplendor", "ref": "tejas"}, {"iast": "tejasvinām", "sa": "तेजस्विनाम्", "gram": "gen. pl. m.", "es": "de los espléndidos", "ref": "tejas", "analisis": "tejasvin (que tiene tejas, brillante, enérgico)"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "jayaḥ", "sa": "जयः", "gram": "nom. sg. m.", "es": "la victoria", "analisis": "√ji (vencer)"}, {"iast": "vyavasāyaḥ", "sa": "व्यवसायः", "gram": "nom. sg. m.", "es": "la resolución, el empeño", "analisis": "vi-ava-√so (decidir, emprender)"}, {"iast": "sattvam", "sa": "सत्त्वम्", "gram": "nom. sg. n.", "es": "la bondad; el vigor", "ref": "sattva", "analisis": "sattva (la guṇa de la claridad y la bondad; también firmeza, energía)"}, {"iast": "sattvavatām", "sa": "सत्त्ववताम्", "gram": "gen. pl. m.", "es": "de los que la tienen, de los buenos", "ref": "sattva", "analisis": "sattvavat (dotado de sattva)"}], "nota": "<p><em>Dyūta</em> es el juego de azar con apuesta, en la épica sobre todo el de dados; <em>chalayatām</em>, «de los que engañan», «de los tramposos». La serie mezcla cosas que no son del mismo orden: un juego, una cualidad (el esplendor), un resultado (la victoria), una disposición (la resolución) y, según se lea, una guṇa (véase la alternativa). <em>Vyavasāya</em> es la misma raíz de la <em>vyavasāyātmikā buddhi</em> de <a class=\"vref\" href=\"capitulo-02.html#v41\" data-v=\"2.41\">2.41</a>, el entendimiento resuelto; aquí, sin embargo, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo glosan como «empeño» (<em>udyama</em>).</p>", "interp": [{"titulo": "También el juego de los tramposos", "html": "<p>El verso incomoda a muchos lectores: ¿cómo puede Kṛṣṇa decir que es el juego de los tramposos? La lista no nombra lo moralmente bueno, sino lo más poderoso o lo más eminente de cada clase, y el criterio lo dará el propio Kṛṣṇa al final: todo lo que tiene grandeza, gloria o fuerza nace de una parte de su esplendor (<a class=\"vref\" href=\"capitulo-10.html#v41\" data-v=\"10.41\">10.41</a>). Entre los que engañan, lo que tiene más fuerza es el juego, que, como dice <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, es el medio de arrebatarle a otro cuanto tiene; Vedānta Deśika añade que permite hacerlo sin esfuerzo y sin faltar a la ley, porque el otro ha aceptado jugar. Ya en <a class=\"vref\" href=\"capitulo-07.html#v12\" data-v=\"7.12\">7.12</a> había dicho que también los estados de rajas y tamas proceden de él, aunque él no está en ellos. En boca de Kṛṣṇa, la frase tiene además un peso propio en el poema: la guerra que va a empezar nació de una partida de dados amañada por <a class=\"t\" href=\"glosario.html#sakuni\" data-t=\"sakuni\">Śakuni</a>, en la que <a class=\"t\" href=\"glosario.html#yudhisthira\" data-t=\"yudhisthira\">Yudhiṣṭhira</a> lo perdió todo.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Soy el juego de dados de los que engañan, el esplendor de los espléndidos; soy la victoria, soy la resolución, soy el vigor de los vigorosos.", "nota": "<p><em>Sattva</em> es el nombre de la primera de las tres <a class=\"t\" href=\"glosario.html#guna\" data-t=\"guna\">guṇas</a>, la de la claridad y la bondad, y así lo toma la traducción principal, con <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> (para éste, sus frutos: la virtud, el conocimiento, el desapego y el poder): «la bondad de los buenos», los que tienen sattva. Pero la palabra significa también, en general, «firmeza, energía, fuerza de ánimo», y en una serie que acaba de nombrar la victoria y la resolución puede leerse en ese sentido, cercano al de <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, que glosa «grandeza de ánimo» (<em>mahā-manastva</em>); en la tradición <a class=\"t\" href=\"glosario.html#gaudiya\" data-t=\"gaudiya\">gauḍīya</a>, Viśvanātha Cakravartī y Prabhupāda dicen «fuerza».</p>"}]}, {"n": 37, "hablante": "krsna", "sa": ["वृष्णीनां वासुदेवोऽस्मि पाण्डवानां धनञ्जयः ।", "मुनीनामप्यहं व्यासः कवीनामुशना कविः ॥३७॥"], "iast": ["vṛṣṇīnāṃ vāsudevo 'smi pāṇḍavānāṃ dhanañjayaḥ", "munīnām apy ahaṃ vyāsaḥ kavīnām uśanā kaviḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Entre los <a class=\"t\" href=\"glosario.html#vrsnis\" data-t=\"vrsnis\">Vṛṣṇis</a> soy <a class=\"t\" href=\"glosario.html#krsna\" data-t=\"krsna\">Vāsudeva</a>; entre los <a class=\"t\" href=\"glosario.html#pandavas\" data-t=\"pandavas\">Pāṇḍavas</a>, <a class=\"t\" href=\"glosario.html#dhananjaya\" data-t=\"dhananjaya\">Dhanañjaya</a>; entre los <a class=\"t\" href=\"glosario.html#muni\" data-t=\"muni\">sabios</a> soy también <a class=\"t\" href=\"glosario.html#vyasa\" data-t=\"vyasa\">Vyāsa</a>; entre los poetas, el poeta <a class=\"t\" href=\"glosario.html#usanas\" data-t=\"usanas\">Uśanas</a>.</span>", "palabras": [{"iast": "vṛṣṇīnām", "sa": "वृष्णीनाम्", "gram": "gen. pl. m.", "es": "de (entre) los Vṛṣṇis", "ref": "vrsnis"}, {"iast": "vāsudevaḥ", "sa": "वासुदेवः", "gram": "nom. sg. m.", "es": "Vāsudeva", "ref": "krsna", "analisis": "vāsudeva (hijo de Vasudeva: Kṛṣṇa)"}, {"iast": "asmi", "sa": "अस्मि", "gram": "1 sg. pres. act.", "es": "soy"}, {"iast": "pāṇḍavānām", "sa": "पाण्डवानाम्", "gram": "gen. pl. m.", "es": "de (entre) los Pāṇḍavas", "ref": "pandavas"}, {"iast": "dhanañjayaḥ", "sa": "धनञ्जयः", "gram": "nom. sg. m.", "es": "Dhanañjaya", "ref": "dhananjaya", "analisis": "dhanam (riqueza) + jaya (que conquista): Arjuna"}, {"iast": "munīnām", "sa": "मुनीनाम्", "gram": "gen. pl. m.", "es": "de (entre) los sabios", "ref": "muni"}, {"iast": "api", "sa": "अपि", "gram": "part.", "es": "también"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "vyāsaḥ", "sa": "व्यासः", "gram": "nom. sg. m.", "es": "Vyāsa", "ref": "vyasa"}, {"iast": "kavīnām", "sa": "कवीनाम्", "gram": "gen. pl. m.", "es": "de (entre) los poetas", "analisis": "kavi (poeta, vidente, sabio)"}, {"iast": "uśanā", "sa": "उशना", "gram": "nom. sg. m.", "es": "Uśanas", "ref": "usanas"}, {"iast": "kaviḥ", "sa": "कविः", "gram": "nom. sg. m.", "es": "el poeta", "analisis": "kavi (poeta, vidente)"}], "nota": "<p><em>Vāsudeva</em>, «el hijo de Vasudeva», es aquí Kṛṣṇa mismo; <em>Dhanañjaya</em>, Arjuna. <em>Kavi</em> es a la vez «poeta» y «vidente, sabio»: en el Veda, el que ve y dice lo que otros no ven. <em>Uśanā</em> es el nominativo de Uśanas, el sabio llamado también Kāvya («descendiente de Kavi») y Śukra, maestro de los <a class=\"t\" href=\"glosario.html#asura\" data-t=\"asura\">asuras</a>.</p>", "interp": [{"titulo": "El que habla, el que escucha y el que lo cuenta", "html": "<p>En medio de la lista, el verso nombra a tres personas presentes en la escena o detrás de ella: Kṛṣṇa, que habla («entre los Vṛṣṇis soy Vāsudeva»); Arjuna, que escucha («entre los Pāṇḍavas, Dhanañjaya»); y <a class=\"t\" href=\"glosario.html#vyasa\" data-t=\"vyasa\">Vyāsa</a>, a quien la tradición atribuye el <a class=\"t\" href=\"glosario.html#mahabharata\" data-t=\"mahabharata\">Mahābhārata</a> y, con él, la Gītā. Arjuna se oye nombrar a sí mismo como una manifestación del que le habla: la distancia entre los dos interlocutores queda, por un momento, suspendida.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 38, "hablante": "krsna", "sa": ["दण्डो दमयतामस्मि नीतिरस्मि जिगीषताम् ।", "मौनं चैवास्मि गुह्यानां ज्ञानं ज्ञानवतामहम् ॥३८॥"], "iast": ["daṇḍo damayatām asmi nītir asmi jigīṣatām", "maunaṃ caivāsmi guhyānāṃ jñānaṃ jñānavatām aham"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Soy la vara del castigo de los que someten, la política de los que buscan la victoria; de los secretos soy también el silencio, y el <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a> de los que conocen.</span>", "palabras": [{"iast": "daṇḍaḥ", "sa": "दण्डः", "gram": "nom. sg. m.", "es": "la vara, el castigo", "analisis": "daṇḍa (bastón, cetro; castigo)"}, {"iast": "damayatām", "sa": "दमयताम्", "gram": "gen. pl. m. part. pres. caus.", "es": "de los que someten", "analisis": "√dam (domar, someter)"}, {"iast": "asmi", "sa": "अस्मि", "gram": "1 sg. pres. act.", "es": "soy"}, {"iast": "nītiḥ", "sa": "नीतिः", "gram": "nom. sg. f.", "es": "la política, el buen gobierno", "analisis": "√nī (conducir, guiar)"}, {"iast": "jigīṣatām", "sa": "जिगीषताम्", "gram": "gen. pl. m. part. pres. desid.", "es": "de los que buscan vencer", "analisis": "desiderativo de √ji (vencer)"}, {"iast": "maunam", "sa": "मौनम्", "gram": "nom. sg. n.", "es": "el silencio", "ref": "muni", "analisis": "derivado de muni (el que guarda silencio)"}, {"iast": "ca eva", "sa": "च एव", "gram": "part.", "es": "y también"}, {"iast": "guhyānām", "sa": "गुह्यानाम्", "gram": "gen. pl. n.", "es": "de los secretos", "analisis": "guhya (lo que se oculta; √guh)"}, {"iast": "jñānam", "sa": "ज्ञानम्", "gram": "nom. sg. n.", "es": "el conocimiento", "ref": "jnana"}, {"iast": "jñānavatām", "sa": "ज्ञानवताम्", "gram": "gen. pl. m.", "es": "de los que conocen", "ref": "jnana"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}], "nota": "<p><em>Daṇḍa</em> es el bastón y, por extensión, el cetro del rey y el castigo que impone; el arte de gobernar se llama en sánscrito <em>daṇḍa-nīti</em>, «la conducción por medio de la vara», y el verso reúne aquí sus dos palabras: <em>daṇḍa</em> y <em>nīti</em>. <em>Jigīṣatām</em>, desiderativo de √ji, «vencer»: «de los que desean vencer». <em>Maunam</em>, «el silencio», deriva de <a class=\"t\" href=\"glosario.html#muni\" data-t=\"muni\">muni</a>, el sabio asceta, en especial el que hace voto de silencio: de todo lo que se oculta, lo más oculto es lo que no se dice: el silencio, explican <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, es lo que guarda los secretos, porque de quien calla no se sabe lo que piensa.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 39, "hablante": "krsna", "sa": ["यच्चापि सर्वभूतानां बीजं तदहमर्जुन ।", "न तदस्ति विना यत्स्यान्मया भूतं चराचरम् ॥३९॥"], "iast": ["yac cāpi sarva-bhūtānāṃ bījaṃ tad aham arjuna", "na tad asti vinā yat syān mayā bhūtaṃ carācaram"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Y lo que es la <a class=\"t\" href=\"glosario.html#bija\" data-t=\"bija\">semilla</a> de todos los seres, eso soy yo, oh <a class=\"t\" href=\"glosario.html#arjuna\" data-t=\"arjuna\">Arjuna</a>: no hay ser, móvil o inmóvil, que pueda existir sin mí.</span>", "palabras": [{"iast": "yat", "sa": "यत्", "gram": "nom. sg. n. pron.", "es": "lo que"}, {"iast": "ca api", "sa": "च अपि", "gram": "part.", "es": "y también"}, {"iast": "sarva-bhūtānām", "sa": "सर्वभूतानाम्", "gram": "gen. pl. n. comp.", "es": "de todos los seres", "analisis": "sarva (todo) + bhūta (ser)"}, {"iast": "bījam", "sa": "बीजम्", "gram": "nom. sg. n.", "es": "la semilla", "ref": "bija"}, {"iast": "tat", "sa": "तत्", "gram": "nom. sg. n. pron.", "es": "eso"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "arjuna", "sa": "अर्जुन", "gram": "voc. sg. m.", "es": "oh Arjuna", "ref": "arjuna"}, {"iast": "na", "sa": "न", "gram": "part.", "es": "no"}, {"iast": "asti", "sa": "अस्ति", "gram": "3 sg. pres. act.", "es": "hay"}, {"iast": "vinā", "sa": "विना", "gram": "prep.", "es": "sin"}, {"iast": "yat", "sa": "यत्", "gram": "nom. sg. n. pron.", "es": "que"}, {"iast": "syāt", "sa": "स्यात्", "gram": "3 sg. opt. act.", "es": "pudiera existir", "analisis": "√as (ser)"}, {"iast": "mayā", "sa": "मया", "gram": "instr. sg. pron.", "es": "(sin) mí"}, {"iast": "bhūtam", "sa": "भूतम्", "gram": "nom. sg. n.", "es": "ser"}, {"iast": "carācaram", "sa": "चराचरम्", "gram": "nom. sg. n. comp.", "es": "móvil o inmóvil", "analisis": "cara (lo que se mueve) + acara (lo que no se mueve)"}], "nota": "<p>La imagen de la semilla ya apareció en <a class=\"vref\" href=\"capitulo-07.html#v10\" data-v=\"7.10\">7.10</a> («la semilla eterna de todos los seres») y en <a class=\"vref\" href=\"capitulo-09.html#v18\" data-v=\"9.18\">9.18</a> («la semilla imperecedera»). Aquí cierra la lista particular con una fórmula general: todo lo que existe, móvil o inmóvil, depende de él para existir.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "una-parte-de-mi-esplendor"}, {"n": 40, "hablante": "krsna", "sa": ["नान्तोऽस्ति मम दिव्यानां विभूतीनां परन्तप ।", "एष तूद्देशतः प्रोक्तो विभूतेर्विस्तरो मया ॥४०॥"], "iast": ["nānto 'sti mama divyānāṃ vibhūtīnāṃ parantapa", "eṣa tūddeśataḥ prokto vibhūter vistaro mayā"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">No tienen fin mis <a class=\"t\" href=\"glosario.html#vibhuti\" data-t=\"vibhuti\">manifestaciones</a> divinas, oh <a class=\"t\" href=\"glosario.html#parantapa\" data-t=\"parantapa\">Parantapa</a>; lo que te he dicho de su extensión ha sido sólo una muestra.</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "part.", "es": "no"}, {"iast": "antaḥ", "sa": "अन्तः", "gram": "nom. sg. m.", "es": "fin"}, {"iast": "asti", "sa": "अस्ति", "gram": "3 sg. pres. act.", "es": "hay"}, {"iast": "mama", "sa": "मम", "gram": "gen. sg. pron.", "es": "mis"}, {"iast": "divyānām", "sa": "दिव्यानाम्", "gram": "gen. pl. f.", "es": "divinas"}, {"iast": "vibhūtīnām", "sa": "विभूतीनाम्", "gram": "gen. pl. f.", "es": "de las manifestaciones", "ref": "vibhuti"}, {"iast": "parantapa", "sa": "परन्तप", "gram": "voc. sg. m.", "es": "oh Parantapa", "ref": "parantapa"}, {"iast": "eṣaḥ", "sa": "एषः", "gram": "nom. sg. m. pron.", "es": "esta"}, {"iast": "tu", "sa": "तु", "gram": "part.", "es": "pero"}, {"iast": "uddeśataḥ", "sa": "उद्देशतः", "gram": "adv.", "es": "a modo de muestra, en resumen", "analisis": "uddeśa (indicación, enunciado breve) + -taḥ"}, {"iast": "proktaḥ", "sa": "प्रोक्तः", "gram": "nom. sg. m. part. pas.", "es": "dicha", "analisis": "pra-√vac (decir, exponer)"}, {"iast": "vibhūteḥ", "sa": "विभूतेः", "gram": "gen. sg. f.", "es": "de la manifestación", "ref": "vibhuti"}, {"iast": "vistaraḥ", "sa": "विस्तरः", "gram": "nom. sg. m.", "es": "la extensión, el detalle", "analisis": "vi-√stṛ (extender)"}, {"iast": "mayā", "sa": "मया", "gram": "instr. sg. pron.", "es": "por mí"}], "nota": "<p><em>Uddeśataḥ</em>: «por vía de indicación», «a modo de enunciado breve», lo contrario de <em>vistareṇa</em>, «por extenso», que Arjuna había pedido en <a class=\"vref\" href=\"capitulo-10.html#v18\" data-v=\"10.18\">10.18</a>. La lista de <a class=\"vref\" href=\"capitulo-10.html#v20\" data-v=\"10.20\">10.20</a>–<a class=\"vref\" href=\"capitulo-10.html#v39\" data-v=\"10.39\">10.39</a> no pretende ser completa: es un muestrario, y el verso siguiente dará el criterio para reconocer las demás.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "una-parte-de-mi-esplendor"}, {"n": 41, "hablante": "krsna", "sa": ["यद्यद्विभूतिमत्सत्त्वं श्रीमदूर्जितमेव वा ।", "तत्तदेवावगच्छ त्वं मम तेजोंऽशसम्भवम् ॥४१॥"], "iast": ["yad yad vibhūtimat sattvaṃ śrīmad ūrjitam eva vā", "tat tad evāvagaccha tvaṃ mama tejoṃ'śa-sambhavam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Todo ser que tenga grandeza, gloria o fuerza, compréndelo así: ha nacido de una parte de mi <a class=\"t\" href=\"glosario.html#tejas\" data-t=\"tejas\">esplendor</a>.</span>", "palabras": [{"iast": "yad yat", "sa": "यद्यत्", "gram": "nom. sg. n. pron.", "es": "todo lo que, cualquier"}, {"iast": "vibhūtimat", "sa": "विभूतिमत्", "gram": "nom. sg. n.", "es": "que tiene grandeza", "ref": "vibhuti", "analisis": "vibhūti + -mat (dotado de)"}, {"iast": "sattvam", "sa": "सत्त्वम्", "gram": "nom. sg. n.", "es": "ser, existente", "analisis": "sattva (aquí: ser, criatura)"}, {"iast": "śrīmat", "sa": "श्रीमत्", "gram": "nom. sg. n.", "es": "glorioso, próspero", "ref": "sri", "analisis": "śrī (esplendor, fortuna) + -mat"}, {"iast": "ūrjitam", "sa": "ऊर्जितम्", "gram": "nom. sg. n.", "es": "vigoroso, poderoso", "analisis": "ūrj (vigor, fuerza)"}, {"iast": "eva vā", "sa": "एव वा", "gram": "part.", "es": "o bien"}, {"iast": "tat tat", "sa": "तत्तत्", "gram": "ac. sg. n. pron.", "es": "eso, cada uno"}, {"iast": "eva", "sa": "एव", "gram": "part.", "es": "precisamente"}, {"iast": "avagaccha", "sa": "अवगच्छ", "gram": "2 sg. impv. act.", "es": "comprende, sabe", "analisis": "ava-√gam (llegar a entender)"}, {"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "mama", "sa": "मम", "gram": "gen. sg. pron.", "es": "de mí"}, {"iast": "tejoṃ'śa-sambhavam", "sa": "तेजोंऽशसम्भवम्", "gram": "ac. sg. n. comp.", "es": "nacido de una parte de mi esplendor", "ref": "tejas", "analisis": "tejas (esplendor) + aṃśa (parte, porción) + sambhava (nacimiento, origen)"}], "nota": "<p>Tres adjetivos dan el criterio de toda la lista: <em>vibhūtimat</em>, «que tiene <a class=\"t\" href=\"glosario.html#vibhuti\" data-t=\"vibhuti\">vibhūti</a>», grandeza o poder; <em>śrīmat</em>, «que tiene <a class=\"t\" href=\"glosario.html#sri\" data-t=\"sri\">śrī</a>», gloria, belleza, fortuna; y <em>ūrjita</em>, «vigoroso». <em>Sattva</em> no designa aquí la guṇa, como en <a class=\"vref\" href=\"capitulo-10.html#v36\" data-v=\"10.36\">10.36</a>, sino cualquier ser: «cosa» (<em>vastu</em>) para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, «ser vivo» para <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>. <em>Aṃśa</em> es «parte, porción»; muchas traducciones dicen «una chispa», imagen que no está en el texto pero que recoge bien la desproporción entre lo que se muestra y su fuente.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "una-parte-de-mi-esplendor"}, {"n": 42, "hablante": "krsna", "sa": ["अथवा बहुनैतेन किं ज्ञातेन तवार्जुन ।", "विष्टभ्याहमिदं कृत्स्नमेकांशेन स्थितो जगत् ॥४२॥"], "iast": ["athavā bahunaitena kiṃ jñātena tavārjuna", "viṣṭabhyāham idaṃ kṛtsnam ekāṃśena sthito jagat"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pero ¿de qué te sirve, oh <a class=\"t\" href=\"glosario.html#arjuna\" data-t=\"arjuna\">Arjuna</a>, saber todo esto con tanto detalle? Yo permanezco sosteniendo este universo entero con una sola parte de mí.</span>", "palabras": [{"iast": "athavā", "sa": "अथवा", "gram": "part.", "es": "pero, o mejor"}, {"iast": "bahunā", "sa": "बहुना", "gram": "instr. sg. n.", "es": "con tanto"}, {"iast": "etena", "sa": "एतेन", "gram": "instr. sg. n. pron.", "es": "con esto"}, {"iast": "kim", "sa": "किम्", "gram": "interr.", "es": "¿qué?"}, {"iast": "jñātena", "sa": "ज्ञातेन", "gram": "instr. sg. n. part. pas.", "es": "con haber sabido", "ref": "jnana", "analisis": "√jñā (conocer)"}, {"iast": "tava", "sa": "तव", "gram": "gen. sg. pron.", "es": "para ti"}, {"iast": "arjuna", "sa": "अर्जुन", "gram": "voc. sg. m.", "es": "oh Arjuna", "ref": "arjuna"}, {"iast": "viṣṭabhya", "sa": "विष्टभ्य", "gram": "abs.", "es": "sosteniendo", "analisis": "vi-√stambh (sostener, apuntalar)"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "idam", "sa": "इदम्", "gram": "ac. sg. n. pron.", "es": "este"}, {"iast": "kṛtsnam", "sa": "कृत्स्नम्", "gram": "ac. sg. n.", "es": "entero"}, {"iast": "ekāṃśena", "sa": "एकांशेन", "gram": "instr. sg. m. comp.", "es": "con una sola parte", "analisis": "eka (uno) + aṃśa (parte)"}, {"iast": "sthitaḥ", "sa": "स्थितः", "gram": "nom. sg. m. part. pas.", "es": "permanezco", "analisis": "√sthā (estar, permanecer)"}, {"iast": "jagat", "sa": "जगत्", "gram": "ac. sg. n.", "es": "el universo", "analisis": "jagat (lo que se mueve, el mundo)"}], "nota": "<p><em>Athavā</em>, «o bien», «pero mejor»: Kṛṣṇa corta la enumeración que Arjuna le había pedido (<a class=\"vref\" href=\"capitulo-10.html#v16\" data-v=\"10.16\">10.16</a>–<a class=\"vref\" href=\"capitulo-10.html#v18\" data-v=\"10.18\">10.18</a>) y pasa de las partes al todo. <em>Viṣṭabhya</em>, de <em>vi-√stambh</em>, «apuntalar, sostener como un pilar». El verso prepara el capítulo 11, donde Arjuna pedirá ver ese todo con sus ojos (<a class=\"vref\" href=\"capitulo-11.html#v3\" data-v=\"11.3\">11.3</a>).</p>", "interp": [{"titulo": "De la lista al todo", "html": "<p>La lista de manifestaciones podría hacer pensar que Kṛṣṇa está repartido en las cosas eminentes, y que lo divino es la suma de lo mejor del mundo. El último verso deshace esa impresión: todo el universo, y no sólo lo eminente, está sostenido por una sola parte de él, y él permanece más allá. Es la misma relación que expresó en <a class=\"vref\" href=\"capitulo-09.html#v4\" data-v=\"9.4\">9.4</a>–<a class=\"vref\" href=\"capitulo-09.html#v5\" data-v=\"9.5\">9.5</a>: los seres están en él, pero él no se agota en ellos. El verso recoge una idea antigua, la del himno del Puruṣa, según el cual los seres son sólo una parte del ser primordial (<em>Ṛg-veda</em> 10.90.3), verso que citan aquí <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Pero ¿de qué te sirve, oh Arjuna, saber todo esto con tanto detalle? Yo permanezco sosteniendo este universo entero con una cuarta parte de mí.", "nota": "<p><em>Aṃśa</em> es «parte, porción», sin precisar cuánta. El himno del Puruṣa dice que todos los seres son una cuarta parte (<em>pāda</em>) del Puruṣa, y tres cuartas partes lo inmortal en el cielo (<em>Ṛg-veda</em> 10.90.3: <em>pādo &#x27;sya viśvā bhūtāni tripād asyāmṛtaṃ divi</em>). Leído a su luz, «una sola parte» sería esa cuarta parte, y así lo entiende <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, que glosa <em>ekāṃśena</em> «con un pie» (<em>eka-pādena</em>); <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> citan el mismo verso, pero glosan sólo «con una mera porción», y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> habla de una parte ínfima, «una diezmilésima de una diezmilésima». La traducción principal no lo precisa, porque el verso tampoco. <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lo entiende al contrario, como una parte ínfima, «una diezmilésima de diezmilésima» de su grandeza, con el <em>Viṣṇu Purāṇa</em> (1.9.53); Viśvanātha Cakravartī y Prabhupāda ven en esa parte al Señor como alma interior de todo (<em>paramātman</em>).</p>"}], "ens": "una-parte-de-mi-esplendor"}], "ensenanzas": [{"id": "todo-procede-de-el", "desde": 2, "hasta": 7, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Todo procede de él: el origen que nadie conoce", "resumen": "<p>Kṛṣṇa es anterior a los dioses y a los grandes sabios, y por eso ellos no conocen su origen; quien lo conoce como no nacido y sin principio queda libre de todo pecado. De él nacen todas las disposiciones de los seres, las gratas y las ingratas —el entendimiento y la calma, pero también el dolor y el miedo—, y de su mente nacieron los primeros sabios y progenitores. Conocer de verdad esta manifestación suya (<em>vibhūti</em>) y su poder (<em>yoga</em>) une con un yoga inquebrantable.</p>"}, {"id": "pensar-en-el-y-hablar-de-el", "desde": 8, "hasta": 9, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Pensar en él y hablar de él con otros", "resumen": "<p>Los que saben que Kṛṣṇa es el origen de todo lo adoran con el corazón: tienen el pensamiento y la vida puestos en él, se explican unos a otros lo que han comprendido y hablan de él sin cesar, y en eso mismo encuentran su contento y su deleite. Es una práctica concreta: el recuerdo constante acompañado de la conversación con otros que buscan lo mismo.</p>"}, {"id": "la-lampara-del-conocimiento", "desde": 10, "hasta": 11, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "El yoga del entendimiento y la lámpara del conocimiento", "resumen": "<p>A los que lo adoran con amor, Kṛṣṇa les da el yoga del entendimiento por el que llegan a él (<a class=\"vref\" href=\"capitulo-02.html#v49\" data-v=\"2.49\">2.49</a>), y por compasión, morando en su interior, disipa la oscuridad de la ignorancia con la lámpara del conocimiento. La disciplina y el conocimiento aparecen aquí como respuesta a la devoción, no como su condición previa.</p>"}, {"id": "el-si-mismo-en-el-corazon-de-los-seres", "desde": 19, "hasta": 20, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "El sí-mismo en el corazón de todos los seres: la clave de las manifestaciones", "resumen": "<p>Antes de enumerar sus manifestaciones, Kṛṣṇa advierte que no las dirá todas, porque no tienen fin, y da la clave para entenderlas: él es el sí-mismo que mora en el corazón de cada ser, y el principio, el medio y el fin de todos. Lo que se nombra después en cada clase es un lugar donde reconocerlo, no una lista cerrada (<a class=\"vref\" href=\"capitulo-10.html#v19\" data-v=\"10.19\">10.19</a>–<a class=\"vref\" href=\"capitulo-10.html#v20\" data-v=\"10.20\">10.20</a>).</p>"}, {"id": "lo-mas-alto-entre-los-dioses-y-los-sabios", "desde": 21, "hasta": 25, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Lo más alto de cada clase: dioses, sabios, aguas y montes", "resumen": "<p>La lista empieza por el mundo de los dioses y del rito: entre los Ādityas, Viṣṇu; entre los Vedas, el Sāma; entre los Rudras, Śiva; entre los sacerdotes, Bṛhaspati; entre los sabios, Bhṛgu; entre los sacrificios, la recitación del mantra. Y pasa a la naturaleza: el sol entre las luces, el océano entre las aguas, el Meru y el Himālaya entre los montes. En cada clase Kṛṣṇa se reconoce en lo que la culmina.</p>"}, {"id": "del-asvattha-a-yama", "desde": 26, "hasta": 29, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Lo excelente de cada clase: del árbol sagrado al señor de los muertos", "resumen": "<p>La lista de manifestaciones sigue con lo más alto de cada clase de seres: el aśvattha entre los árboles, Nārada entre los sabios divinos, Kapila entre los perfectos; los animales prodigiosos nacidos del batido del océano; el rey entre los hombres; el rayo, la vaca de los deseos, el amor que engendra; las serpientes divinas, Varuṇa, Aryaman y Yama (<a class=\"vref\" href=\"capitulo-10.html#v26\" data-v=\"10.26\">10.26</a>–<a class=\"vref\" href=\"capitulo-10.html#v29\" data-v=\"10.29\">10.29</a>). En cada clase, lo que sobresale es una señal de Kṛṣṇa, incluso cuando es la muerte o el deseo, a condición de verlo como suyo (<a class=\"vref\" href=\"capitulo-10.html#v41\" data-v=\"10.41\">10.41</a>).</p>"}, {"id": "el-tiempo-que-todo-lo-arrebata", "desde": 33, "hasta": 34, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "El tiempo imperecedero y la muerte que todo lo arrebata", "resumen": "<p>En medio de la lista de manifestaciones, Kṛṣṇa se identifica con el tiempo que no se agota y con la muerte que todo se lleva, y a la vez con el origen de lo que ha de nacer (así <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> entienden «la prosperidad de los que han de prosperar»). No es sólo lo mejor de cada clase: es también lo que hace aparecer y desaparecer a todas. Esta cara de lo divino, la del tiempo que destruye, es la que Arjuna verá con espanto en <a class=\"vref\" href=\"capitulo-11.html#v32\" data-v=\"11.32\">11.32</a>.</p>"}, {"id": "una-parte-de-mi-esplendor", "desde": 39, "hasta": 42, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Una parte de su esplendor: el criterio de la lista", "resumen": "<p>Kṛṣṇa cierra la lista de sus <a class=\"t\" href=\"glosario.html#vibhuti\" data-t=\"vibhuti\">manifestaciones</a> con tres afirmaciones. Es la semilla de todos los seres, y nada existe sin él (<a class=\"vref\" href=\"capitulo-10.html#v39\" data-v=\"10.39\">10.39</a>). Lo dicho es sólo una muestra, porque sus manifestaciones no tienen fin (<a class=\"vref\" href=\"capitulo-10.html#v40\" data-v=\"10.40\">10.40</a>). Y da el criterio para reconocer las que no ha nombrado: todo lo que tiene grandeza, gloria o fuerza nace de una parte de su esplendor (<a class=\"vref\" href=\"capitulo-10.html#v41\" data-v=\"10.41\">10.41</a>). Pero no hay que buscarlo sólo en lo eminente: el universo entero está sostenido por una sola parte de él, y él permanece más allá (<a class=\"vref\" href=\"capitulo-10.html#v42\" data-v=\"10.42\">10.42</a>).</p>"}]};
